UPDATE public.grammar_rules SET content = '{"sections":[{"title_en":"What the Genitive Shows","content_de":"Der Genitiv antwortet auf die Frage Wessen? Er zeigt Besitz oder Zugehörigkeit.","content_en":"The genitive answers the question Wessen? (whose?)\n\n• Wessen Auto ist das? — Das ist das Auto des Mannes.\n  (Whose car is that? — That is the man''s car.)\n\n• Wessen Tasche ist das? — Das ist die Tasche der Frau.\n  (Whose bag is that? — That is the woman''s bag.)\n\nThe genitive shows possession, belonging, or relationship between nouns."},{"title_en":"Word Order: Possessed + Possessor","content_de":"Im Deutschen: Besitz + Besitzer (im Genitiv): das Auto des Mannes.","content_en":"In German, the order is usually:\nPOSSESSED item + possessor (in genitive)\n\n• das Auto des Mannes (the car of-the man = the man''s car)\n• die Tür des Hauses (the door of-the house = the house''s door)\n• der Anfang des Films (the beginning of-the film)\n\nThis is the opposite of English ''the man''s car'' where the possessor comes first!"}]}'::jsonb
WHERE id = '19c7f484-7c51-430e-b10b-1aa3c7f1c1da'::uuid AND content = '{"sections":[{"title_en":"What the Genitive Shows","content_de":"Der Genitiv antwortet auf die Frage Wessen? Er zeigt Besitz oder Zugehörigkeit.","content_en":"The genitive answers the question Wessen? (whose?)\n\n• Wessen Auto ist das? — Das ist das Auto des Mannes.\n  (Whose car is that? — That is the man''s car.)\n\n• Wessen Tasche ist das? — Das ist die Tasche der Frau.\n  (Whose bag is that? — That is the woman''s bag.)\n\nThe genitive shows possession, belonging, or relationship between nouns."},{"title_en":"Word Order: Possessed + Possessor","content_de":"Im Deutschen: Besitz + besitzer (im Genitiv). das Auto des Mannes.","content_en":"In German, the order is usually:\nPOSSESSED item + possessor (in genitive)\n\n• das Auto des Mannes (the car of-the man = the man''s car)\n• die Tür des Hauses (the door of-the house = the house''s door)\n• der Anfang des films (the beginning of-the film)\n\nThis is the opposite of English ''the man''s car'' where the possessor comes first!"}]}'::jsonb;

UPDATE public.grammar_rules SET title_de = 'Wiederholung: die Genitivformen'
WHERE id = '64fc4a83-e8af-41f5-886a-c4753bd84b01'::uuid AND title_de = 'Genitiv-Formen Wiederholung';

UPDATE public.grammar_rules SET content = '{"rows":[["Der Mann ist nett.","Sein Auto ist rot.","Der Mann, dessen Auto rot ist, ist nett."],["Die Frau wohnt hier.","Ihr Haus ist groß.","Die Frau, deren Haus groß ist, wohnt hier."],["Die Kinder spielen.","Ihre Eltern arbeiten.","Die Kinder, deren Eltern arbeiten, spielen."]],"headers":["Main Clause","Possession","Full Sentence"],"description_de":"dessen ersetzt sein (m/n). deren ersetzt ihr (f/pl). Zeigt Besitz!","description_en":"dessen = whose (masculine/neuter). deren = whose (feminine/plural). Shows possession!"}'::jsonb
WHERE id = '382d0b22-0064-441e-bb5c-2d0cf60f00da'::uuid AND content = '{"rows":[["Der Mann ist nett.","Sein Auto ist rot.","Der Mann, dessen Auto rot ist, ist nett."],["Die Frau wohnt hier.","Ihr Haus ist groß.","Die Frau, deren Haus groß ist, wohnt hier."],["Die Kinder spielen.","Ihre Eltern arbeiten.","Die Kinder, deren Eltern arbeiten, spielen."]],"headers":["Main Clause","Possession","Full Sentence"],"description_de":"dessen = dessen (m/n). deren = deren (f/pl). Zeigt Besitz!","description_en":"dessen = whose (masculine/neuter). deren = whose (feminine/plural). Shows possession!"}'::jsonb;

UPDATE public.grammar_rules SET content = '{"sections":[{"title_en":"What Is a Relative Clause?","content_de":"Ein Relativsatz gibt mehr Informationen über ein Nomen. Ein Relativpronomen leitet ihn ein.","content_en":"A relative clause gives more information about a noun. It''s introduced by a relative pronoun (der, die, das, etc.).\n\nMain clause: Ich sehe einen Mann.\nRelative clause: Der Mann ist groß.\nCombined: Ich sehe einen Mann, der groß ist.\n(I see a man who is tall.)\n\nThe relative clause is inserted after the noun it describes."},{"title_en":"Two Key Questions","content_de":"Zwei Fragen: (1) Welches Geschlecht hat das Bezugswort? (2) Welche Funktion hat das Relativpronomen im Relativsatz?","content_en":"To choose the correct relative pronoun, ask:\n\n1. What gender is the noun I''m referring to?\n   → der Mann (masc.), die Frau (fem.), das Kind (neut.), die Leute (plural)\n\n2. What function does the relative pronoun have in the relative clause?\n   → Is it the subject (nominative)? Or the direct object (accusative)?\n\nThe gender comes from the noun. The case comes from the function."},{"title_en":"Verb Goes to the End!","content_de":"Relativsätze sind Nebensätze — das konjugierte Verb geht ans Ende!","content_en":"Relative clauses are subordinate clauses — the conjugated verb goes to the end!\n\n• Der Mann, der dort steht, ist mein Bruder.\n  (The man who is standing there is my brother.)\n\n• Das Buch, das ich lese, ist interessant.\n  (The book that I am reading is interesting.)\n\nComma before the relative pronoun, verb at the end!"}]}'::jsonb
WHERE id = '49606078-4e74-413e-ba3c-ae5e6e3aad28'::uuid AND content = '{"sections":[{"title_en":"What Is a Relative Clause?","content_de":"Ein Relativsatz gibt mehr information über ein Nomen. Er wird durch ein Relativpronomen eingeleitet.","content_en":"A relative clause gives more information about a noun. It''s introduced by a relative pronoun (der, die, das, etc.).\n\nMain clause: Ich sehe einen Mann.\nRelative clause: Der Mann ist groß.\nCombined: Ich sehe einen Mann, der groß ist.\n(I see a man who is tall.)\n\nThe relative clause is inserted after the noun it describes."},{"title_en":"Two Key Questions","content_de":"Zwei Fragen: (1) Welches Geschlecht hat das Bezugswort? (2) Welche Funktion hat das Relativpronomen im Relativsatz?","content_en":"To choose the correct relative pronoun, ask:\n\n1. What gender is the noun I''m referring to?\n   → der Mann (masc.), die Frau (fem.), das Kind (neut.), die Leute (plural)\n\n2. What function does the relative pronoun have in the relative clause?\n   → Is it the subject (nominative)? Or the direct object (accusative)?\n\nThe gender comes from the noun. The case comes from the function."},{"title_en":"Verb Goes to the End!","content_de":"Relativsätze sind Nebensätze — das konjugierte Verb geht ans Ende!","content_en":"Relative clauses are subordinate clauses — the conjugated verb goes to the end!\n\n• Der Mann, der dort steht, ist mein Bruder.\n  (The man who is standing there is my brother.)\n\n• Das Buch, das ich lese, ist interessant.\n  (The book that I am reading is interesting.)\n\nComma before the relative pronoun, verb at the end!"}]}'::jsonb;

UPDATE public.grammar_rules SET content = '{"sections":[{"title_en":"When to Use Accusative","content_de":"Akkusativ wenn das Relativpronomen direktes Objekt ist — es empfängt die Aktion.","content_en":"Use accusative when the relative pronoun is the direct object of the relative clause — it''s receiving the action.\n\n• Der Mann, den ich sehe, ist groß.\n  (The man whom I see is tall.)\n  → ''den'' is the object of ''sehe'' (ich sehe den Mann)\n\n• Das Buch, das ich lese, ist gut.\n  (The book that I am reading is good.)\n  → ''das'' is the object of ''lese'' (ich lese das Buch)"},{"title_en":"Accusative Forms","content_de":"Nur maskulin ändert sich! der → den. Feminin, Neutrum, Plural bleiben gleich.","content_en":"MASCULINE: den — Der Mann, den ich sehe...\nFEMININE: die — Die Frau, die ich sehe...\nNEUTER: das — Das Kind, das ich sehe...\nPLURAL: die — Die Leute, die ich sehe...\n\nOnly masculine changes! (der → den, just like regular accusative)"},{"title_en":"How to Identify Accusative","content_de":"Frage: Gibt es ein anderes Subjekt im Relativsatz? Wenn ja → Akkusativ.","content_en":"Ask: Is there another subject in the relative clause?\n\n• Der Film, den ich gesehen habe, war toll.\n  ''ich'' is the subject, ''den'' is the object → accusative\n\n• Der Film, der interessant war, ist vorbei.\n  ''der'' is the subject → nominative\n\nIf someone/something else does the action to the relative pronoun = accusative."}]}'::jsonb
WHERE id = '7a8f87a5-b26a-41fc-bb9a-c68e1db5c205'::uuid AND content = '{"sections":[{"title_en":"When to Use Accusative","content_de":"Akkusativ wenn das Relativpronomen direktes Objekt ist — es empfängt die Aktion.","content_en":"Use accusative when the relative pronoun is the direct object of the relative clause — it''s receiving the action.\n\n• Der Mann, den ich sehe, ist groß.\n  (The man whom I see is tall.)\n  → ''den'' is the object of ''sehe'' (ich sehe den Mann)\n\n• Das Buch, das ich lese, ist gut.\n  (The book that I am reading is good.)\n  → ''das'' is the object of ''lese'' (ich lese das Buch)"},{"title_en":"Accusative Forms","content_de":"Nur maskulin ändert sich! der → den. Feminin, Neutrum, Plural bleiben gleich.","content_en":"MASCULINE: den — Der Mann, den ich sehe...\nFEMININE: die — Die Frau, die ich sehe...\nNEUTER: das — Das Kind, das ich sehe...\nPLURAL: die — Die Leute, die ich sehe...\n\nOnly masculine changes! (der → den, just like regular accusative)"},{"title_en":"How to Identify Accusative","content_de":"Frage: Gibt es ein anderes Subjekt im Relativsatz? Wenn ja → Akkusativ.","content_en":"Ask: Is there another subject in the relative clause?\n\n• Der Film, den Ich gesehen habe, war toll.\n  ''ich'' is the subject, ''den'' is the object → accusative\n\n• Der Film, der interessant war, ist vorbei.\n  ''der'' is the subject → nominative\n\nIf someone/something else does the action to the relative pronoun = accusative."}]}'::jsonb;

UPDATE public.grammar_rules SET content = '{"text_de":"um/ohne/anstatt ... zu gilt nur, wenn beide Sätze das gleiche Subjekt haben! Bei verschiedenen Subjekten brauchst du \"damit\" — das lernst du später im Kurs.","text_en":"um/ohne/anstatt ... zu only works when both clauses share the same subject! If the subjects are different, you need \"damit\" instead — you will learn that later in the course.","example_de":"Ich lerne, um zu verstehen. (ich / ich = gleiches Subjekt)","example_en":"Same subject: um zu."}'::jsonb
WHERE id = 'adba8282-abd7-4646-9c62-dcd80fd440f7'::uuid AND content = '{"text_de":"um/ohne/anstatt ... zu nur wenn Beide Sätze das Gleiche Subjekt haben! Bei verschiedenen Subjekten: damit/ohne dass/anstatt dass.","text_en":"um/ohne/anstatt ... zu can only be used when both clauses have the same subject! If subjects are different, use damit/ohne dass/anstatt dass instead.","example_de":"Ich lerne, um zu verstehen. (I learn, I understand = same subject) vs. Ich erkläre es, damit du verstehst. (I explain, you understand = different subjects)","example_en":"Same subject: um zu. Different subjects: damit + conjugated verb."}'::jsonb;

