INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '0339f580-f9ce-5389-b408-fbf5e90af442'::uuid, 'c2eb46c0-7d0d-4049-bcc5-3b03d1518c60'::uuid, 'dialogue', 'With the Landlord: A Phone Call About the Heating', 'Beim Vermieter: Telefonat wegen der Heizung', '{"lines":[{"de":"Guten Tag, Frau Klein. Ich rufe wegen der Heizung an.","en":"Hello Mrs Klein. I''m calling about the heating.","speaker":"Herr Berger","highlight":"wegen der Heizung"},{"de":"Was ist denn los? Wegen der Reparatur habe ich noch nichts gehört.","en":"What''s wrong? I haven''t heard anything about the repair yet.","speaker":"Frau Klein","highlight":"Wegen der Reparatur"},{"de":"Trotz meines Anrufs vor einer Woche ist noch nichts passiert. Können Sie das innerhalb einer Woche reparieren?","en":"Despite my call a week ago, nothing has happened yet. Can you fix it within a week?","speaker":"Herr Berger","highlight":"Trotz meines Anrufs vor einer Woche"},{"de":"Während des Winters sind wir sehr beschäftigt, aber ich kümmere mich sofort um das Problem.","en":"During the winter we are very busy, but I''ll take care of the problem right away.","speaker":"Frau Klein","highlight":"Während des Winters"},{"de":"Wegen der Kälte in der Wohnung möchte ich das schnell klären.","en":"Because of the cold in the apartment, I want to sort this out quickly.","speaker":"Herr Berger","highlight":"Wegen der Kälte"},{"de":"Ich verstehe. Trotz der vielen Arbeit schicke ich morgen einen Techniker.","en":"I understand. Despite all the work, I''ll send a technician tomorrow.","speaker":"Frau Klein","highlight":"Trotz der vielen Arbeit"}],"context_de":"Ein Mieter ruft seine Vermieterin wegen der Heizung an.","context_en":"A tenant calls his landlord about the heating."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '0339f580-f9ce-5389-b408-fbf5e90af442'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '171a9071-c21c-52dc-a85e-e9949a6409e0'::uuid, 'c2eb46c0-7d0d-4049-bcc5-3b03d1518c60'::uuid, 'table', 'Genitive Prepositions with Possessive Articles and Plural', 'Genitiv-Präpositionen mit Possessivpronomen und Plural', '{"rows":[["wegen","wegen meines Termins (because of my appointment)","wegen der hohen Kosten (because of the high costs)"],["trotz","trotz seiner Erkältung (despite his cold)","trotz der ständigen Probleme (despite the constant problems)"],["während","während unserer Reise (during our trip)","während der Ferien (during the holidays)"],["innerhalb","innerhalb ihrer Frist (within her deadline)","innerhalb der ersten Wochen (within the first weeks)"]],"headers":["Präposition","Beispiel (Possessiv)","Beispiel (Plural)"],"description_de":"Nach diesen Präpositionen stehen auch Possessivpronomen und Plural im Genitiv.","description_en":"Possessive articles and plural nouns after these prepositions also take genitive endings."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'wegen, trotz, während, innerhalb + possessive/plural still take genitive endings.', 'wegen, trotz, während, innerhalb + Possessiv/Plural bleiben im Genitiv.', NULL, NULL, 'Possessive articles and plural nouns follow the same genitive endings as der/die/das.', 'Possessivpronomen und Plural folgen den gleichen Genitiv-Endungen wie der/die/das.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '171a9071-c21c-52dc-a85e-e9949a6409e0'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '7cb2b2f0-6faa-5bca-9503-1d0908b5ce3b'::uuid, 'c2eb46c0-7d0d-4049-bcc5-3b03d1518c60'::uuid, 'common_mistakes', 'Common Mistakes: wegen, statt, während', 'Häufige Fehler: wegen, statt, während', '{"intro_de":"Diese vier Fehler passieren beim Schreiben am häufigsten.","intro_en":"These four mistakes are the most common ones in writing.","mistakes":[{"wrong":"Wegen dem Verkehr komme ich später.","correct":"Wegen des Verkehrs komme ich später.","explanation_de":"wegen braucht den Genitiv, nicht den Dativ. Die Formen zeigt dir die Regel »Umgangssprache: Dativ statt Genitiv«.","explanation_en":"wegen takes the genitive, not the dative. You can find the forms in the rule \"Spoken German: Dative Instead of Genitive\"."},{"wrong":"Statt dem Auto nehme ich den Bus.","correct":"Statt des Autos nehme ich den Bus.","explanation_de":"statt (= anstatt) braucht wie wegen den Genitiv, nicht den Dativ.","explanation_en":"statt (= anstatt) takes the genitive, not the dative, just like wegen."},{"wrong":"Trotz den Problemen arbeiten wir weiter.","correct":"Trotz der Probleme arbeiten wir weiter.","explanation_de":"Plural-Genitiv nach trotz: der, nicht den (das wäre Dativ Plural).","explanation_en":"Plural genitive after trotz is der, not den (which would be dative plural)."},{"wrong":"Während dem Urlaub war ich in Spanien.","correct":"Während des Urlaubs war ich in Spanien.","explanation_de":"während braucht Genitiv, nicht Dativ. Hinweis: während hat später im Kurs noch eine zweite Funktion.","explanation_en":"während takes the genitive, not the dative. Note: während gets a second function later in the course."}]}'::jsonb, 8, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Genitive prepositions never take dem or den Auto – always des/der + Genitiv-Nomen.', 'Genitiv-Präpositionen nehmen nie dem oder den – immer des/der + Genitiv-Nomen.', NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '7cb2b2f0-6faa-5bca-9503-1d0908b5ce3b'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '89ee7a1c-4a33-5fde-960b-a5cfc2d37f5e'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 'table', 'zu-Infinitive After Nouns and Adjectives', 'zu-Infinitiv nach Nomen und Adjektiven', '{"rows":[["die Möglichkeit, ... zu","the chance to","Ich habe die Möglichkeit, im Ausland zu arbeiten."],["die Chance, ... zu","the opportunity to","Das ist deine Chance, dich zu verbessern."],["es ist wichtig, ... zu","it is important to","Es ist wichtig, den Vertrag zu lesen."],["keine Zeit, ... zu","no time to","Ich habe keine Zeit, das zu erledigen."]],"headers":["Ausdruck","Englisch","Beispiel"],"description_de":"Nomen und Adjektive stehen oft mit zu + Infinitiv. Ein Komma trennt den Infinitivsatz.","description_en":"Nouns and adjectives often combine with zu + infinitive. A comma separates the infinitive clause."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'die Möglichkeit/Chance + zu = an opportunity to do. es ist + Adjektiv + zu = an opinion about doing.', 'die Möglichkeit/Chance + zu = eine Gelegenheit. es ist + Adjektiv + zu = eine Meinung.', NULL, NULL, 'Nouns like Möglichkeit, Chance, and Zeit combine with zu + infinitive exactly like the adjective expressions from the earlier table.', 'Nomen wie Möglichkeit, Chance und Zeit stehen mit zu + Infinitiv, genau wie die Adjektiv-Ausdrücke aus der früheren Tabelle.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '89ee7a1c-4a33-5fde-960b-a5cfc2d37f5e'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'c345671f-aa3e-5f5d-afed-2f99cdbba5f4'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 'dialogue', 'Job Interview and Further Training', 'Bewerbungsgespräch und Weiterbildung', '{"lines":[{"de":"Warum haben Sie sich entschieden, sich bei uns zu bewerben?","en":"Why did you decide to apply with us?","speaker":"Frau Berger","highlight":"sich zu bewerben"},{"de":"Ich habe vor, meine Deutschkenntnisse weiter zu verbessern.","en":"I plan to improve my German skills further.","speaker":"Herr Ahmadi","highlight":"vor, ... zu verbessern"},{"de":"Haben Sie auch Lust, an einer Weiterbildung teilzunehmen?","en":"Do you also feel like taking part in further training?","speaker":"Frau Berger","highlight":"Lust, ... teilzunehmen"},{"de":"Ja, es ist mir wichtig, mich fachlich weiterzuentwickeln.","en":"Yes, it is important to me to develop professionally.","speaker":"Herr Ahmadi","highlight":"wichtig, ... weiterzuentwickeln"},{"de":"Vergessen Sie nicht, uns bis Freitag zu antworten.","en":"Don''t forget to answer us by Friday.","speaker":"Frau Berger","highlight":"vergessen, ... zu antworten"},{"de":"Ich hoffe, mich schnell wieder bei Ihnen zu melden.","en":"I hope to get back in touch with you quickly.","speaker":"Herr Ahmadi","highlight":"hoffe, ... zu melden"}],"context_de":"Ein Vorstellungsgespräch für eine Stelle mit Weiterbildung.","context_en":"A job interview for a position that includes further training."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'c345671f-aa3e-5f5d-afed-2f99cdbba5f4'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '9f05fa06-de93-5743-b2c6-65c9df955145'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 'common_mistakes', 'Common Mistakes with zu + Infinitive', 'Häufige Fehler mit zu + Infinitiv', '{"intro_de":"Diese drei Fehler tauchen oft in Prüfungen auf.","intro_en":"These three mistakes turn up often in exams.","mistakes":[{"wrong":"Ich kann zu schwimmen.","correct":"Ich kann schwimmen.","explanation_de":"Modalverben stehen ohne zu direkt mit dem Infinitiv.","explanation_en":"Modal verbs take a plain infinitive, never zu."},{"wrong":"Vergiss nicht, das Zimmer zu aufräumen!","correct":"Vergiss nicht, das Zimmer aufzuräumen!","explanation_de":"Bei trennbaren Verben steht zu in der Mitte: aufzuräumen.","explanation_en":"For separable verbs, zu goes in the middle: aufzuräumen."},{"wrong":"Ich habe keine Zeit Deutsch zu lernen.","correct":"Ich habe keine Zeit, Deutsch zu lernen.","explanation_de":"Der Infinitivsatz hängt vom Nomen Zeit ab; hier ist das Komma Pflicht.","explanation_en":"The infinitive clause depends on the noun Zeit; here the comma is obligatory."}]}'::jsonb, 8, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Modal verbs never take zu. Separable verbs put zu in the middle. In this course we always write the comma before an extended infinitive clause.', 'Modalverben nie mit zu. Trennbare Verben: zu in der Mitte. In diesem Kurs schreiben wir das Komma vor dem erweiterten Infinitiv immer.', NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '9f05fa06-de93-5743-b2c6-65c9df955145'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '50481176-ae5b-59ac-b2c5-5203d5f8692e'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 'table', 'sollte, müsste, dürfte, könnte: Giving Advice Politely', 'sollte, müsste, dürfte, könnte: höflich raten', '{"rows":[["sollte","Ratschlag / Empfehlung","Du solltest das Formular vor dem Termin ausfüllen."],["müsste","eigentlich nötig","Ich müsste eigentlich noch die Anlage schicken."],["dürfte","vorsichtige Vermutung","Das dürfte kein Problem sein."],["könnte","höflicher Vorschlag","Sie könnten sich direkt beim Amt melden."]],"headers":["Form","Funktion","Beispiel"],"description_de":"Diese Formen wirken höflicher als der Imperativ. Im Sprechen Teil 3 und im halbformellen Brief sind sie sehr üblich.","description_en":"These forms sound more polite than the imperative. They are common in the Sprechen Teil 3 exam task and in a semi-formal letter."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'sollte = should, müsste = really should, dürfte = probably, könnte = could — all softer than a direct command.', 'sollte = ein Rat, müsste = eigentlich nötig, dürfte = eine Vermutung, könnte = ein Vorschlag — alle weicher als ein Befehl.', 'Sie könnten... and Sie sollten... are the standard polite forms in a formal letter or exam task.', 'Sie könnten... und Sie sollten... sind die üblichen höflichen Formen im formellen Brief oder in der Prüfung.', 'sollte, müsste, dürfte, könnte are all Konjunktiv II of modal verbs, used here for advice, not for hypotheticals.', 'sollte, müsste, dürfte, könnte sind Konjunktiv II von Modalverben, hier für Ratschläge, nicht für Hypothesen.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '50481176-ae5b-59ac-b2c5-5203d5f8692e'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'c21ccb11-a32a-5abf-bb18-b4720844b02a'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 'dialogue', 'Advice Among Colleagues', 'Ratschläge unter Kollegen', '{"lines":[{"de":"Ich hätte gern mehr Zeit für die Weiterbildung, aber der Chef sagt Nein.","en":"I would like more time for further training, but the boss says no.","speaker":"Frau Nowak","highlight":"hätte gern"},{"de":"An deiner Stelle würde ich noch einmal mit ihm sprechen.","en":"In your place, I would talk to him again.","speaker":"Herr Keller","highlight":"würde ich"},{"de":"Meinst du, das würde etwas ändern?","en":"Do you think that would change something?","speaker":"Frau Nowak","highlight":"würde"},{"de":"Du solltest wenigstens fragen. Vielleicht wäre ein Kompromiss möglich.","en":"You should at least ask. Maybe a compromise would be possible.","speaker":"Herr Keller","highlight":"solltest / wäre"},{"de":"Wenn ich mehr Erfahrung hätte, könnte ich auch selbst entscheiden.","en":"If I had more experience, I could decide myself too.","speaker":"Frau Nowak","highlight":"hätte / könnte"},{"de":"Das dürfte bald der Fall sein. Du machst das wirklich gut.","en":"That should soon be the case. You are doing this really well.","speaker":"Herr Keller","highlight":"dürfte"}],"context_de":"Zwei Kollegen sprechen über eine Weiterbildung.","context_en":"Two colleagues talk about further training."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'c21ccb11-a32a-5abf-bb18-b4720844b02a'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '4a1803f0-abd8-5149-8420-1302095ee629'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 'common_mistakes', 'Common Mistakes with wäre/hätte', 'Häufige Fehler mit wäre/hätte', '{"intro_de":"Diese drei Fehler tauchen oft in Prüfungen auf.","intro_en":"These three mistakes turn up often in exams.","mistakes":[{"wrong":"Wenn ich du wärst, würde ich das anders machen.","correct":"Wenn ich du wäre, würde ich das anders machen.","explanation_de":"Das Verb richtet sich nach dem Subjekt (ich), nicht nach du: ich wäre, nicht du wärst.","explanation_en":"The verb agrees with the subject (ich), not with du: ich wäre, not du wärst."},{"wrong":"Das könnte sein besser.","correct":"Das könnte besser sein.","explanation_de":"Nach dem Modalverb könnte steht der Infinitiv am Satzende: könnte besser sein.","explanation_en":"After the modal könnte, the infinitive goes to the end of the sentence: könnte besser sein."},{"wrong":"Das wäre nett von du.","correct":"Das wäre nett von dir.","explanation_de":"Nach von steht der Dativ: von dir, nicht von du.","explanation_en":"von takes the dative: von dir, not von du."}]}'::jsonb, 8, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'wäre agrees with the subject, not with du. No würde next to könnten or sollten. von always takes the dative.', 'wäre richtet sich nach dem Subjekt, nicht nach du. Neben könnten oder sollten steht kein würde. Nach von steht immer der Dativ.', NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '4a1803f0-abd8-5149-8420-1302095ee629'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'a367a589-d9ab-5574-b99d-b601beb86b23'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 'table', 'Preposition + Relative Pronoun: More Examples', 'Präposition + Relativpronomen: mehr Beispiele', '{"rows":[["mit (+ Dativ)","dem","Der Kurs, mit dem ich anfange, ist schwer."],["bei (+ Dativ)","der","Die Ärztin, bei der ich einen Termin habe, ist nett."],["für (+ Akkusativ)","die","Die Stelle, für die ich mich bewerbe, ist interessant."],["über (+ Akkusativ)","das","Das Thema, über das wir sprechen, ist schwierig."],["von (+ Dativ)","denen","Die Kollegen, von denen ich erzählt habe, sind nett."]],"headers":["Präposition","Relativpronomen","Beispielsatz"],"description_de":"Die Präposition bestimmt den Kasus, das Nomen bestimmt das Geschlecht.","description_en":"The preposition determines the case; the noun determines the gender."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Preposition + relative pronoun stay together; the preposition sets the case.', 'Präposition + Relativpronomen bleiben zusammen; die Präposition bestimmt den Kasus.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'a367a589-d9ab-5574-b99d-b601beb86b23'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'c4be8aef-3d88-548e-a415-984d18cec7e0'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 'dialogue', 'At the Apartment Viewing', 'Bei der Wohnungsbesichtigung', '{"lines":[{"de":"Das ist das Zimmer, dessen Fenster nach Süden zeigt.","en":"This is the room whose window faces south.","speaker":"Frau Nowak","highlight":"dessen Fenster"},{"de":"Und die Nachbarn, mit denen ich hier zu tun habe – sind die freundlich?","en":"And the neighbours I''d be dealing with here – are they friendly?","speaker":"Herr Aydin","highlight":"mit denen ich hier zu tun habe"},{"de":"Ja, das ist die Familie, deren Kinder auch hier wohnen.","en":"Yes, that''s the family whose children also live here.","speaker":"Frau Nowak","highlight":"deren Kinder"},{"de":"Und der Keller, von dem Sie gesprochen haben – gehört der auch zur Wohnung?","en":"And the basement you mentioned – is that part of the apartment too?","speaker":"Herr Aydin","highlight":"von dem Sie gesprochen haben"},{"de":"Ja, natürlich. Das ist der Bereich, wo Sie auch Fahrräder abstellen können.","en":"Yes, of course. That''s the area where you can also park bicycles.","speaker":"Frau Nowak","highlight":"wo Sie auch Fahrräder abstellen können"},{"de":"Gut, das ist also die Wohnung, an die ich schon lange gedacht habe.","en":"Good, so this is the apartment I''ve been thinking about for a long time.","speaker":"Herr Aydin","highlight":"an die ich schon lange gedacht habe"}],"context_de":"Ein Mieter besichtigt eine Wohnung mit der Vermieterin.","context_en":"A tenant views an apartment with the landlady."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'c4be8aef-3d88-548e-a415-984d18cec7e0'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ea50ecbf-13e7-5351-a65d-9143ea8cd6d3'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 'common_mistakes', 'Common Mistakes: Preposition, dessen/deren, Comma', 'Häufige Fehler: Präposition, dessen/deren, Komma', '{"intro_de":"Diese vier Fehler tauchen oft bei Präpositionen und Kommas auf.","intro_en":"These four mistakes often occur with prepositions and commas.","mistakes":[{"wrong":"Der Chef, ich arbeite für, ist streng.","correct":"Der Chef, für den ich arbeite, ist streng.","explanation_de":"Die Präposition steht nicht am Ende! Präposition + Relativpronomen: für den ich arbeite.","explanation_en":"The preposition doesn''t go at the end! Preposition + relative pronoun: für den ich arbeite."},{"wrong":"Der Mann, deren Auto rot ist, ist mein Nachbar.","correct":"Der Mann, dessen Auto rot ist, ist mein Nachbar.","explanation_de":"der Mann ist maskulin → dessen, nicht deren.","explanation_en":"der Mann is masculine → dessen, not deren."},{"wrong":"Die Frau dessen Sohn hier arbeitet ist neu.","correct":"Die Frau, deren Sohn hier arbeitet, ist neu.","explanation_de":"die Frau ist feminin → deren. Es fehlen auch die Kommas!","explanation_en":"die Frau is feminine → deren. Also, the commas are missing!"},{"wrong":"Die Kollegen mit denen ich arbeite sind hilfsbereit.","correct":"Die Kollegen, mit denen ich arbeite, sind hilfsbereit.","explanation_de":"Vor und nach dem Relativsatz stehen Kommas, auch bei Präposition + Relativpronomen.","explanation_en":"Commas go before and after the relative clause, even with preposition + relative pronoun."}]}'::jsonb, 8, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Preposition + relative pronoun never split. dessen for him/it, deren for her/them. Commas always around the clause.', 'Präposition + Relativpronomen bleiben zusammen. dessen für ihn/es, deren für sie/sie (Pl.). Immer Kommas um den Satz.', NULL, NULL, 'wo is fine for a simple place; with a fixed preposition like bei/mit, preposition + relative pronoun is more common in writing.', '»wo« ist bei einfachen Orten richtig; bei einer festen Präposition wie bei/mit ist Präposition + Relativpronomen im Schreiben üblicher.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ea50ecbf-13e7-5351-a65d-9143ea8cd6d3'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'de323796-a9ef-54d7-b5e7-1e34d1fa5f69'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 'table', '(an)statt ... zu and the Same-Subject Rule', '(an)statt ... zu und die Regel vom gleichen Subjekt', '{"rows":[["Anstatt zu arbeiten, geht er spazieren.","Instead of working, he goes for a walk.","gleiches Subjekt: er / er"],["Ich helfe dir, anstatt selbst zu lernen.","I help you instead of studying myself.","gleiches Subjekt: ich / ich"],["(zwei verschiedene Subjekte)","(two different subjects)","kein zu-Satz möglich"]],"headers":["Beispiel","Englisch","Hinweis"],"description_de":"um, ohne und (an)statt + zu funktionieren nur, wenn beide Satzteile dasselbe Subjekt haben. Bei zwei verschiedenen Subjekten geht das nicht.","description_en":"um, ohne and (an)statt + zu only work when both parts of the sentence share the same subject. With two different subjects, this construction does not work."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Same subject twice? Use zu. Two different subjects? Then um/ohne/(an)statt ... zu does not work.', 'Zweimal dasselbe Subjekt? zu benutzen. Zwei verschiedene Subjekte? Dann geht um/ohne/(an)statt ... zu nicht.', NULL, NULL, 'Check the subject of both actions first; only matching subjects allow um/ohne/(an)statt ... zu.', 'Prüfe zuerst das Subjekt beider Handlungen; nur bei gleichem Subjekt geht um/ohne/(an)statt ... zu.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'de323796-a9ef-54d7-b5e7-1e34d1fa5f69'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '156dfb4b-42f1-5086-9673-937351621213'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 'dialogue', 'Moving and Planning a Trip', 'Umzug und Reiseplanung', '{"lines":[{"de":"Wir packen heute Kisten, um am Wochenende umzuziehen.","en":"We are packing boxes today in order to move this weekend.","speaker":"Julia","highlight":"um ... umzuziehen"},{"de":"Ohne deine Hilfe würde ich das nicht schaffen.","en":"Without your help I would not manage that.","speaker":"Mark","highlight":"Ohne deine Hilfe"},{"de":"Kein Problem! Statt fernzusehen, helfe ich dir lieber.","en":"No problem! Instead of watching TV, I''d rather help you.","speaker":"Julia","highlight":"Statt fernzusehen"},{"de":"Wir planen später die Reise, um uns zu erholen.","en":"We''ll plan the trip later in order to relax.","speaker":"Mark","highlight":"um ... zu erholen"},{"de":"Gute Idee. Ich habe keine Lust, den ganzen Tag zu arbeiten.","en":"Good idea. I don''t feel like working all day.","speaker":"Julia","highlight":"Lust, ... zu arbeiten"},{"de":"Genau. Anstatt zu arbeiten, sollten wir Pläne machen.","en":"Exactly. Instead of working, we should make plans.","speaker":"Mark","highlight":"Anstatt zu arbeiten"}],"context_de":"Zwei Freunde sprechen über den Umzug und die nächste Reise.","context_en":"Two friends talk about the move and the next trip."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '156dfb4b-42f1-5086-9673-937351621213'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'a20c0eb2-4a2c-588c-9541-c3b376c5fd96'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 'common_mistakes', 'Common Mistakes with um/ohne/(an)statt ... zu', 'Häufige Fehler mit um/ohne/(an)statt ... zu', '{"intro_de":"Diese drei Fehler tauchen oft in Prüfungen auf.","intro_en":"These three mistakes turn up often in exams.","mistakes":[{"wrong":"Ich erkläre es noch einmal, um du es besser verstehst.","correct":"Hier geht um ... zu nicht — die Subjekte sind verschieden.","explanation_de":"um ... zu geht nur bei gleichem Subjekt. Für zwei Subjekte brauchst du \"damit\" — das lernst du später im Kurs.","explanation_en":"um ... zu only works with the same subject. For two subjects you need \"damit\" — you learn that later in the course."},{"wrong":"Sie ruft an, um zu fragen nach den Öffnungszeiten.","correct":"Sie ruft an, um nach den Öffnungszeiten zu fragen.","explanation_de":"zu + Infinitiv stehen ganz am Ende; das Objekt (nach den Öffnungszeiten) kommt davor.","explanation_en":"zu + infinitive go at the very end; the object (nach den Öffnungszeiten) comes before them."},{"wrong":"Sie ging ohne sich zu verabschieden.","correct":"Sie ging, ohne sich zu verabschieden.","explanation_de":"Vor ohne ... zu (erweiterter Infinitivsatz) steht ein Komma.","explanation_en":"A comma comes before ohne ... zu when it introduces an extended infinitive clause."}]}'::jsonb, 8, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'um ... zu only works with the same subject. The object comes before zu + infinitive. A comma opens the extended clause.', 'um ... zu geht nur bei gleichem Subjekt. Das Objekt steht vor zu + Infinitiv. Ein Komma öffnet den erweiterten Satz.', NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'a20c0eb2-4a2c-588c-9541-c3b376c5fd96'::uuid);

-- Examples
INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '39f8c29f-402e-5728-8410-81879dd72ecf'::uuid, 'c2eb46c0-7d0d-4049-bcc5-3b03d1518c60'::uuid, 'Wegen meines Termins beim Arzt komme ich später.', 'Because of my appointment at the doctor''s, I will come later.', 'Wegen meines Termins', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'meines is the masculine genitive possessive after wegen.', 'meines ist das maskuline Genitiv-Possessivpronomen nach wegen.', '{"Wegen":"because of","meines Termins":"my appointment (masc. gen.)","beim Arzt":"at the doctor''s","komme ich":"I come","später":"later"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '39f8c29f-402e-5728-8410-81879dd72ecf'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '9b8d7d5b-c944-5db3-8fee-a69c3115d7c5'::uuid, 'c2eb46c0-7d0d-4049-bcc5-3b03d1518c60'::uuid, 'Aufgrund der hohen Miete suchen wir eine kleinere Wohnung.', 'Because of the high rent, we are looking for a smaller apartment.', 'Aufgrund der hohen Miete', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'aufgrund is a genitive preposition; die Miete is feminine, so der.', 'aufgrund ist eine Genitiv-Präposition; die Miete ist feminin: der.', '{"Aufgrund":"because of","der hohen Miete":"the high rent (fem. gen.)","suchen wir":"we are looking for","eine kleinere Wohnung":"a smaller apartment"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '9b8d7d5b-c944-5db3-8fee-a69c3115d7c5'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '0c413d42-1d56-503b-8001-ffb1072a3f3a'::uuid, 'c2eb46c0-7d0d-4049-bcc5-3b03d1518c60'::uuid, 'Trotz seiner Erkältung arbeitet er weiter.', 'Despite his cold, he keeps working.', 'Trotz seiner Erkältung', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'seiner is the feminine genitive possessive after trotz, matching die Erkältung.', 'seiner ist das feminine Genitiv-Possessivpronomen nach trotz, passend zu die Erkältung.', '{"Trotz":"despite","seiner Erkältung":"his cold (fem. gen.)","arbeitet er":"he works","weiter":"on"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '0c413d42-1d56-503b-8001-ffb1072a3f3a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '185ba338-3189-5ec0-a173-28ec8801b655'::uuid, 'c2eb46c0-7d0d-4049-bcc5-3b03d1518c60'::uuid, 'Innerhalb der ersten Wochen lernt man die Kollegen kennen.', 'Within the first weeks, you get to know your colleagues.', 'Innerhalb der ersten Wochen', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'der ersten Wochen is the plural genitive after innerhalb.', 'der ersten Wochen ist der Plural-Genitiv nach innerhalb.', '{"Innerhalb":"within","der ersten Wochen":"the first weeks (pl. gen.)","lernt man":"one gets to know","die Kollegen":"the colleagues","kennen":"(to) know"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '185ba338-3189-5ec0-a173-28ec8801b655'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'f7f14120-1e02-5651-b103-5210686688fb'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 'Ich habe vor, meine Deutschkenntnisse zu verbessern.', 'I plan to improve my German skills.', 'vor, ... zu verbessern', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'vorhaben splits (habe vor); comma, then zu + infinitive at the end.', 'vorhaben trennt sich (habe vor); Komma, dann zu + Infinitiv am Ende.', '{"Ich habe vor":"I plan","meine Deutschkenntnisse":"my German skills","zu verbessern":"to improve"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'f7f14120-1e02-5651-b103-5210686688fb'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'e6ff4c10-e97f-56e0-a399-83b3d1e53521'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 'Es ist mir wichtig, pünktlich zur Arbeit zu kommen.', 'It is important to me to arrive at work on time.', 'wichtig, ... zu kommen', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'es ist wichtig + comma + zu + infinitive at the end.', 'es ist wichtig + Komma + zu + Infinitiv am Ende.', '{"Es ist mir wichtig":"It is important to me","pünktlich":"punctually","zur Arbeit":"to work","zu kommen":"to come"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'e6ff4c10-e97f-56e0-a399-83b3d1e53521'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'ab5f9ec7-56a5-5fe2-adef-0cb3433db502'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 'Ich habe keine Zeit, das Formular heute auszufüllen.', 'I have no time to fill out the form today.', 'auszufüllen', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'ausfüllen is separable: aus-zu-füllen.', 'ausfüllen ist trennbar: aus-zu-füllen.', '{"Ich habe keine Zeit":"I have no time","das Formular":"the form","heute":"today","auszufüllen":"to fill out"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'ab5f9ec7-56a5-5fe2-adef-0cb3433db502'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'cab756fe-2e97-511d-b7bc-9080cd87f94e'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 'Vergiss nicht, den Termin abzusagen.', 'Don''t forget to cancel the appointment.', 'abzusagen', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'absagen is separable: ab-zu-sagen.', 'absagen ist trennbar: ab-zu-sagen.', '{"Vergiss nicht":"Don''t forget","den Termin":"the appointment","abzusagen":"to cancel"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'cab756fe-2e97-511d-b7bc-9080cd87f94e'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '3247476e-3ec8-559c-a7eb-6e2955464e6e'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 'Wenn ich mehr Zeit hätte, könnte ich öfter Sport machen.', 'If I had more time, I could exercise more often.', 'hätte ... könnte', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'wenn-clause with hätte (verb at end), main clause with könnte + infinitive.', 'wenn-Satz mit hätte (Verb am Ende), Hauptsatz mit könnte + Infinitiv.', '{"Wenn":"if","ich":"I","mehr Zeit":"more time","hätte":"had (Konj. II of haben)","könnte ich":"I could","öfter":"more often","Sport machen":"exercise, do sports"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '3247476e-3ec8-559c-a7eb-6e2955464e6e'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '39852898-776e-5ed2-a4d1-7fc72d11d00e'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 'Sie hätte gern einen Termin am Montag.', 'She would like an appointment on Monday.', 'hätte gern', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'hätte gern (would like) is very common when arranging appointments.', 'hätte gern ist beim Vereinbaren von Terminen sehr üblich.', '{"Sie":"She","hätte gern":"would like","einen Termin":"an appointment","am Montag":"on Monday"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '39852898-776e-5ed2-a4d1-7fc72d11d00e'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'c75c6559-f733-5810-b474-a56c7ebd9039'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 'Wärst du bereit, den Antrag zu unterschreiben?', 'Would you be willing to sign the application?', 'Wärst du bereit', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wärst du (would you be) + adjective + zu-infinitive clause.', 'Wärst du + Adjektiv + zu-Infinitivsatz.', '{"Wärst du":"Would you be","bereit":"willing","den Antrag":"the application","zu unterschreiben":"to sign"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'c75c6559-f733-5810-b474-a56c7ebd9039'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'f7dd4b63-6940-53a4-ac63-48ff8c39d399'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 'An ihrer Stelle würde ich zuerst mit der Kollegin sprechen.', 'In her place, I would talk to the colleague first.', 'würde ich', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'An ihrer Stelle + würde ich is a common way to give someone advice.', 'An ihrer Stelle + würde ich gibt einen Rat.', '{"An ihrer Stelle":"In her place","würde ich":"I would","zuerst":"first","mit der Kollegin":"with the colleague","sprechen":"talk"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'f7dd4b63-6940-53a4-ac63-48ff8c39d399'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '15ce477b-27c1-5404-816b-2e578acf69ee'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 'Die Firma, bei der ich arbeite, sucht neue Mitarbeiter.', 'The company I work for is looking for new employees.', 'bei der', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'bei takes the dative, and Firma is feminine, so the pronoun is der.', 'bei braucht den Dativ, und Firma ist feminin: der.', '{"Die Firma":"the company","bei der":"at which (fem. dat.)","ich arbeite":"I work","sucht":"is looking for","neue Mitarbeiter":"new employees"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '15ce477b-27c1-5404-816b-2e578acf69ee'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '585558a0-48e5-529e-a83d-68f5dceb4da2'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 'Der Kollege, dessen Büro neben meinem liegt, ist sehr hilfsbereit.', 'The colleague whose office is next to mine is very helpful.', 'dessen Büro', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'dessen is the masculine genitive relative pronoun, matching der Kollege.', 'dessen ist das maskuline Genitiv-Relativpronomen, passend zu der Kollege.', '{"Der Kollege":"the colleague","dessen Büro":"whose office (masc. gen.)","neben meinem":"next to mine","liegt":"is located","ist sehr hilfsbereit":"is very helpful"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '585558a0-48e5-529e-a83d-68f5dceb4da2'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '33cbc81b-6c21-5362-a12b-565aeaea622e'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 'Die Nachbarn, deren Garten so schön ist, feiern morgen ein Fest.', 'The neighbours whose garden is so beautiful are having a party tomorrow.', 'deren Garten', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'deren is the plural genitive relative pronoun, matching die Nachbarn.', 'deren ist das Plural-Genitiv-Relativpronomen, passend zu die Nachbarn.', '{"Die Nachbarn":"the neighbours","deren Garten":"whose garden (pl. gen.)","so schön ist":"is so beautiful","feiern":"are celebrating","morgen":"tomorrow","ein Fest":"a party"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '33cbc81b-6c21-5362-a12b-565aeaea622e'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '6223fa04-9cb7-50c2-b39e-98bae1d8d356'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 'Das ist der Bereich, wo Sie Ihr Fahrrad abstellen können.', 'That is the area where you can park your bike.', 'wo', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'wo replaces a relative pronoun when referring to a place.', 'wo ersetzt das Relativpronomen bei Ortsangaben.', '{"Das ist":"that is","der Bereich":"the area","wo":"where","Sie":"you (formal)","Ihr Fahrrad":"your bike","abstellen können":"can park"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '6223fa04-9cb7-50c2-b39e-98bae1d8d356'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '7d33227e-5a86-573a-a612-6816d8deeffb'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 'Wir packen die Koffer, um pünktlich am Flughafen zu sein.', 'We are packing the suitcases in order to be at the airport on time.', 'um ... zu sein', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'um ... zu = purpose. Why pack? To be at the airport on time.', 'um ... zu = Zweck. Warum packen? Um pünktlich am Flughafen zu sein.', '{"Wir packen":"We are packing","die Koffer":"the suitcases","um":"in order","pünktlich":"on time","am Flughafen":"at the airport","zu sein":"to be"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '7d33227e-5a86-573a-a612-6816d8deeffb'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '90d7aeb3-8163-5567-b2ff-78c6d1745edf'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 'Anstatt zu Hause zu bleiben, gehen wir spazieren.', 'Instead of staying home, we go for a walk.', 'Anstatt ... zu bleiben', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'anstatt ... zu = instead of doing. What we don''t do + what we do instead.', 'anstatt ... zu nennt die Handlung, die nicht passiert.', '{"Anstatt":"Instead of","zu Hause":"at home","zu bleiben":"staying","gehen wir":"we go","spazieren":"for a walk"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '90d7aeb3-8163-5567-b2ff-78c6d1745edf'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'e109e38f-51d4-5a3b-be6a-cd1d6d752c74'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 'Er verließ das Büro, ohne die Tür abzuschließen.', 'He left the office without locking the door.', 'ohne ... abzuschließen', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'ohne ... zu with a separable verb: ab-zu-schließen.', 'ohne ... zu mit trennbarem Verb: ab-zu-schließen.', '{"Er verließ":"He left","das Büro":"the office","ohne":"without","die Tür":"the door","abzuschließen":"locking"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'e109e38f-51d4-5a3b-be6a-cd1d6d752c74'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '0645cddb-4c20-5ccc-8532-231d25355736'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 'Ich schreibe eine Liste, um nichts zu vergessen.', 'I write a list in order to forget nothing.', 'um ... zu vergessen', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'um ... zu = purpose. Why write a list? To forget nothing.', 'um ... zu = Zweck. Warum eine Liste schreiben? Um nichts zu vergessen.', '{"Ich schreibe":"I write","eine Liste":"a list","um":"in order","nichts":"nothing","zu vergessen":"to forget"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '0645cddb-4c20-5ccc-8532-231d25355736'::uuid);

