INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6290a3f0-11ae-5c16-97bd-c82f2cf363f1'::uuid, '49257ffb-e391-48df-9e93-8a5ec675e939'::uuid, 4, 'fill_blank', 'Das ist das Büro ___ Chefs. (mein)', 'That is my boss''s office. Masculine noun, genitive, possessive article. Base form: mein.', NULL, 'meines', '["meines"]'::jsonb, 'mein takes the masculine genitive ending: meines Chefs.', 'mein + maskulines Genitiv-Nomen: meines Chefs.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine genitive possessive: mein + -es = meines.', 'Maskulin Genitiv Possessiv: mein + -es = meines.', 'How the Genitive Works'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6290a3f0-11ae-5c16-97bd-c82f2cf363f1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6f6e127f-9030-5d3e-a088-516b0b011161'::uuid, '49257ffb-e391-48df-9e93-8a5ec675e939'::uuid, 4, 'fill_blank', 'Wegen ___ Erkältung bleibt er zu Hause. (sein)', 'Because of his cold, he stays at home. wegen + genitive, feminine noun, possessive article. Base form: sein.', NULL, 'seiner', '["seiner"]'::jsonb, 'wegen takes the genitive and Erkältung is feminine, so sein becomes seiner.', 'wegen + Genitiv. Erkältung ist feminin: seiner.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine genitive possessive: sein + -er = seiner.', 'Feminin Genitiv Possessiv: sein + -er = seiner.', 'How the Genitive Works'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6f6e127f-9030-5d3e-a088-516b0b011161'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2d5866c9-47d5-56fc-9be8-b9aa5f6186d5'::uuid, '49257ffb-e391-48df-9e93-8a5ec675e939'::uuid, 4, 'fill_blank', 'Die Meinung ___ Kollegin ist mir wichtig. (unser)', 'Our colleague''s (f.) opinion matters to me. Feminine noun, genitive, possessive article. Base form: unser.', NULL, 'unserer', '["unserer"]'::jsonb, 'Feminine genitive: unser takes -er, so unser becomes unserer.', 'Feminin Genitiv: unser + -er = unserer.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine genitive possessive: unser + -er = unserer.', 'Feminin Genitiv Possessiv: unser + -er = unserer.', 'How the Genitive Works'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2d5866c9-47d5-56fc-9be8-b9aa5f6186d5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2185df10-09ba-5291-9211-818140d90b1f'::uuid, '49257ffb-e391-48df-9e93-8a5ec675e939'::uuid, 4, 'fill_blank', 'Wessen Fahrrad ist das? – Das ist das Fahrrad ___ Sohnes. (ihr)', 'Whose bike is that? – That is her son''s bike. Masculine noun, genitive, possessive article after ''wessen''. Base form: ihr.', NULL, 'ihres', '["ihres"]'::jsonb, 'Masculine genitive: ihr takes -es, so ihr becomes ihres.', 'Maskulin Genitiv: ihr + -es = ihres.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine genitive possessive: ihr + -es = ihres.', 'Maskulin Genitiv Possessiv: ihr + -es = ihres.', 'Genitive Article Changes'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2185df10-09ba-5291-9211-818140d90b1f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ef51bad4-a949-5de2-8c6e-3485396211d5'::uuid, '49257ffb-e391-48df-9e93-8a5ec675e939'::uuid, 5, 'sentence_building', 'Schreib den Satz: [das Auto / mein / Bruder / sein / neu]', 'Write the sentence: My brother''s car is new. Genitive possessive, masculine noun, sein conjugates to ist. Start with ''Das Auto''.', NULL, 'Das Auto meines Bruders ist neu.', '["Das Auto meines Bruders ist neu.","Das Auto meines Bruders ist neu"]'::jsonb, 'mein takes the masculine genitive ending, and Bruder adds -s: meines Bruders.', 'mein + maskulines Genitiv-Nomen: meines Bruders.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine genitive: mein + -es on the article, -s on the noun.', 'Maskulin Genitiv: mein + -es beim Artikel, -s beim Nomen.', 'Genitive Article Changes'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ef51bad4-a949-5de2-8c6e-3485396211d5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3a9e47af-4982-5461-bcf7-38d6c0697d0b'::uuid, '49257ffb-e391-48df-9e93-8a5ec675e939'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Die Tür des Büro ist offen."', 'Find the error and write the sentence correctly: "Die Tür des Büro ist offen." (neuter noun, genitive)', NULL, 'Die Tür des Büros ist offen.', '["Die Tür des Büros ist offen.","Die Tür des Büros ist offen"]'::jsonb, 'Büro is neuter and adds -s in the genitive: des Büros.', 'Büro ist neutrum und bekommt im Genitiv ein -s: des Büros.', NULL, 21, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Neuter genitive nouns add -s: des Büros, like des Autos.', 'Neutrum Genitiv-Nomen bekommen -s: des Büros, wie des Autos.', 'When to Add -s vs -es to Nouns'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3a9e47af-4982-5461-bcf7-38d6c0697d0b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e66b742c-e1c5-5135-89d2-deb594c88c5d'::uuid, '49257ffb-e391-48df-9e93-8a5ec675e939'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Wohnung / unser / Nachbarin / sein / klein]', 'Write the sentence: Our neighbour''s (f.) apartment is small. Genitive possessive, feminine noun, sein conjugates to ist. Start with ''Die Wohnung''.', NULL, 'Die Wohnung unserer Nachbarin ist klein.', '["Die Wohnung unserer Nachbarin ist klein.","Die Wohnung unserer Nachbarin ist klein"]'::jsonb, 'Feminine genitive: unser takes -er before a feminine noun.', 'Feminin Genitiv: unser + -er = unserer.', NULL, 22, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine genitive possessive: unser + -er = unserer.', 'Feminin Genitiv Possessiv: unser + -er = unserer.', 'How the Genitive Works'
