SELECT 'd0295800-4474-55b2-a5fb-4c138346dd9a'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 5, 'sentence_building', 'Schreib den Satz: [sie / haben / die Möglichkeit / sich / bei der Krankenkasse / zu / versichern]', 'Write the sentence: She has the chance to get insured with the health insurance fund. Conjugate ''haben'' to ''hat''. Start with ''Sie''.', NULL, 'Sie hat die Möglichkeit, sich bei der Krankenkasse zu versichern.', '["Sie hat die Möglichkeit, sich bei der Krankenkasse zu versichern.","Sie hat die Möglichkeit, sich bei der Krankenkasse zu versichern"]'::jsonb, 'haben + die Möglichkeit + comma + zu + infinitive at the end.', 'haben + die Möglichkeit + Komma + zu + Infinitiv am Ende.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'die Möglichkeit + comma + zu + infinitive, just like vorhaben.', 'die Möglichkeit + Komma + zu + Infinitiv, wie bei vorhaben.', 'zu-Infinitive After Nouns and Adjectives'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd0295800-4474-55b2-a5fb-4c138346dd9a'::uuid);

