WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '60540251-66e2-5ee1-9867-7fba9abfb620'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '20a01cc9-90b2-551d-ad34-488973130757'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 5, 'sentence_building', 'Schreib den Satz: [sie / haben / Lust / ins Museum / zu / gehen]', 'Write the sentence: She feels like going to the museum. ''sie'' = she; conjugate ''haben'' to ''hat''. Start with ''Sie''.', NULL, 'Sie hat Lust, ins Museum zu gehen.', '["Sie hat Lust, ins Museum zu gehen.","Sie hat Lust, ins Museum zu gehen"]'::jsonb, 'hat Lust + comma + zu + infinitive at the end.', 'hat Lust + Komma + zu + Infinitiv am Ende.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'hat Lust, ... zu + infinitive is the standard pattern.', 'hat Lust, ... zu + Infinitiv ist das Standardmuster.', 'Expressions with zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '20a01cc9-90b2-551d-ad34-488973130757'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '370e727a-65e7-5be6-a83e-37d2158d4115'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich muss zu gehen."', 'Find the error and write the sentence correctly: "Ich muss zu gehen." (modal verbs take a plain infinitive)', NULL, 'Ich muss gehen.', '["Ich muss gehen.","Ich muss gehen"]'::jsonb, 'Modal verbs like müssen never take zu; the plain infinitive follows directly.', 'Modalverben wie müssen stehen nie mit zu; der reine Infinitiv folgt direkt.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'müssen + infinitive, no zu.', 'müssen + Infinitiv, kein zu.', 'Common Mistakes with zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '370e727a-65e7-5be6-a83e-37d2158d4115'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f6e213e3-43da-510a-912c-cc93a9be69a5'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Vergiss nicht, mich zu abholen!"', 'Find the error and write the sentence correctly: "Vergiss nicht, mich zu abholen!" (separable verb)', NULL, 'Vergiss nicht, mich abzuholen!', '["Vergiss nicht, mich abzuholen!","Vergiss nicht, mich abzuholen"]'::jsonb, 'abholen is separable: zu goes in the middle, abzuholen.', 'abholen ist trennbar: zu in der Mitte, abzuholen.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Separable verbs: prefix + zu + verb stem = one word.', 'Trennbar: Präfix + zu + Verbstamm = ein Wort.', 'Common Mistakes with zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f6e213e3-43da-510a-912c-cc93a9be69a5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c69e2b19-fe7e-5a85-a6f1-403e239c0627'::uuid, 'c56d9360-77e2-4781-b3e4-3a64d02c3ef2'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Sie hat Zeit dir zu helfen."', 'Find the error and write the sentence correctly: "Sie hat Zeit dir zu helfen." (missing comma)', NULL, 'Sie hat Zeit, dir zu helfen.', '["Sie hat Zeit, dir zu helfen.","Sie hat Zeit, dir zu helfen"]'::jsonb, 'The infinitive clause depends on the noun Zeit; here the comma is obligatory.', 'Der Infinitivsatz hängt vom Nomen Zeit ab; hier ist das Komma Pflicht.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Comma marks the start of the infinitive clause.', 'Das Komma markiert den Beginn des Infinitivsatzes.', 'Common Mistakes with zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c69e2b19-fe7e-5a85-a6f1-403e239c0627'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '462fedb8-93d0-53a3-8d20-4617e1debaa5'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 4, 'fill_blank', 'Ich ___ gern mehr Geduld mit den Kollegen.', 'I would like to have more patience with my colleagues. ich-form. Base form: haben (hätte).', NULL, 'hätte', '["hätte"]'::jsonb, 'haben becomes hätte in Konjunktiv II, same pattern as ''Ich hätte gern einen Kaffee.''', 'haben wird zu hätte im Konjunktiv II, wie bei ''Ich hätte gern einen Kaffee.''', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'hätte is the ich-form of haben''s Konjunktiv II.', 'hätte ist die ich-Form des Konjunktivs II von haben.', 'hätte Conjugation (would have)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '462fedb8-93d0-53a3-8d20-4617e1debaa5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '47811255-c5aa-5a64-97f7-3f57df784597'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 4, 'fill_blank', 'Wenn sie den Termin verschieben könnte, ___ das für alle einfacher.', 'If she could reschedule the appointment, that would be easier for everyone. Main clause, das-form. Base form: sein (wäre).', NULL, 'wäre', '["wäre"]'::jsonb, 'sein becomes wäre; used here for ''das wäre einfacher'' (that would be easier).', 'sein wird zu wäre; hier für ''das wäre einfacher''.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'das (es-form) takes wäre, like er/sie/es.', 'das (es-Form) nimmt wäre, wie er/sie/es.', 'wäre Conjugation (would be)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '47811255-c5aa-5a64-97f7-3f57df784597'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bc7e867b-a5ee-5b74-aa0b-86e472a17937'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 4, 'fill_blank', 'Ihr ___ eigentlich pünktlicher zum Termin kommen.', 'You (plural) really should arrive at the appointment more punctually. ihr-form. Base form: müssen (müsste).', NULL, 'müsstet', '["müsstet"]'::jsonb, 'müssen becomes müsste, and the ihr-form adds -t: müsstet.', 'müssen wird zu müsste, ihr-Form mit -t: müsstet.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr müsstet is the plural informal form of müsste.', 'ihr müsstet ist die Plural-Form von müsste.', 'Modal Verbs Have Special Forms Too'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bc7e867b-a5ee-5b74-aa0b-86e472a17937'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e24fbadf-24b8-5b0a-8a13-6e258295ad48'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 4, 'fill_blank', 'Die Kollegen ___ das wohl verstehen.', 'The colleagues would probably understand that. Plural subject, cautious guess. Base form: dürfen (dürfte).', NULL, 'dürften', '["dürften"]'::jsonb, 'dürfte expresses a careful guess; the plural form is dürften.', 'dürfte drückt eine vorsichtige Vermutung aus; Plural: dürften.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Plural of dürfte is dürften, like wären/hätten.', 'Plural von dürfte ist dürften, wie wären/hätten.', 'sollte, müsste, dürfte, könnte: Giving Advice Politely'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e24fbadf-24b8-5b0a-8a13-6e258295ad48'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '43b44421-5197-56a3-ab2e-b6d2d4760eb4'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / mehr Geduld / mit ihm / haben]', 'Write the sentence: I would have more patience with him. Konjunktiv II: conjugate ''haben'' to ''hätte''. Start with ''Ich''.', NULL, 'Ich hätte mehr Geduld mit ihm.', '["Ich hätte mehr Geduld mit ihm.","Ich hätte mehr Geduld mit ihm"]'::jsonb, 'haben becomes hätte (ich-form); the object and prepositional phrase follow.', 'haben wird zu hätte (ich-Form); Objekt und Präpositionalphrase folgen.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'hätte + object; no infinitive needed since hätte is itself the Konjunktiv II verb.', 'hätte + Objekt; kein Infinitiv nötig, da hätte selbst das Konjunktiv-II-Verb ist.', 'hätte Conjugation (would have)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '43b44421-5197-56a3-ab2e-b6d2d4760eb4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b69c2bad-bca5-552d-943d-edcc945f8f81'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wenn / der Antrag / fertig / sein / werden / ich / sofort / anrufen]', 'Write the sentence: If the application were ready, I would call right away. wenn-clause with wäre (sein); main clause with würde (werden) + ich. Start with ''Wenn''.', NULL, 'Wenn der Antrag fertig wäre, würde ich sofort anrufen.', '["Wenn der Antrag fertig wäre, würde ich sofort anrufen.","Wenn der Antrag fertig wäre, würde ich sofort anrufen"]'::jsonb, 'wenn-clause: verb (wäre) at the end. Main clause: würde in position 2 (after the comma), then ich, then the infinitive anrufen at the end.', 'wenn-Satz: Verb (wäre) am Ende. Hauptsatz: würde an Position 2 (nach dem Komma), dann ich, dann Infinitiv anrufen am Ende.', NULL, 14, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Two clauses: wenn + wäre (end), then würde + ich + sofort + anrufen.', 'Zwei Sätze: wenn + wäre (Ende), dann würde + ich + sofort + anrufen.', 'Wenn-Clauses with wäre/hätte'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b69c2bad-bca5-552d-943d-edcc945f8f81'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '47bad49c-f408-55f2-a2ae-a4e000f9fa70'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 5, 'sentence_building', 'Schreib den Satz: [an seiner Stelle / ich / zuerst / mit dem Chef / sprechen / werden]', 'Write the sentence: In his place, I would talk to the boss first. Konjunktiv II with würde (werden). Start with ''An seiner Stelle''.', NULL, 'An seiner Stelle würde ich zuerst mit dem Chef sprechen.', '["An seiner Stelle würde ich zuerst mit dem Chef sprechen.","An seiner Stelle würde ich zuerst mit dem Chef sprechen"]'::jsonb, 'Adverbial ''An seiner Stelle'' in position 1, würde in position 2 (verb-second).', 'Adverbiale ''An seiner Stelle'' an Position 1, würde an Position 2.', NULL, 15, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The position-1 phrase pushes würde to position 2; the subject ich follows.', 'Die Phrase an Position 1 schiebt würde an Position 2; das Subjekt ich folgt.', 'Advice Among Colleagues'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '47bad49c-f408-55f2-a2ae-a4e000f9fa70'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '950ee86a-a9de-5f18-9059-4c8ebadf4d89'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Du sollte mehr Geduld haben."', 'Find the error and write the sentence correctly: "Du sollte mehr Geduld haben." (du-form needs the -st ending)', NULL, 'Du solltest mehr Geduld haben.', '["Du solltest mehr Geduld haben.","Du solltest mehr Geduld haben"]'::jsonb, 'The du-form needs the -st ending: solltest, not sollte.', 'Die du-Form braucht die Endung -st: solltest, nicht sollte.', NULL, 16, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sollte + du = solltest.', 'sollte + du = solltest.', 'Modal Verbs Have Special Forms Too'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '950ee86a-a9de-5f18-9059-4c8ebadf4d89'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'de327954-11e2-551e-937e-ed266998182b'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Wenn er mehr Zeit hätte, er würde helfen."', 'Find the error and write the sentence correctly: "Wenn er mehr Zeit hätte, er würde helfen." (verb-second in the main clause)', NULL, 'Wenn er mehr Zeit hätte, würde er helfen.', '["Wenn er mehr Zeit hätte, würde er helfen.","Wenn er mehr Zeit hätte, würde er helfen"]'::jsonb, 'After the comma, the main clause starts with the verb (würde), then the subject (er) follows.', 'Nach dem Komma beginnt der Hauptsatz mit dem Verb (würde), dann folgt das Subjekt (er).', NULL, 17, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'wenn-clause first counts as position 1, so würde takes position 2.', 'Der wenn-Satz zählt als Position 1; würde steht dann an Position 2.', 'Wenn-Clauses with wäre/hätte'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'de327954-11e2-551e-937e-ed266998182b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5639e5da-2847-5ad7-95b8-21669aeaf428'::uuid, 'e8508d78-5926-4828-8e65-6b4005377d36'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich hätte gern ein Platz."', 'Find the error and write the sentence correctly: "Ich hätte gern ein Platz." (accusative masculine ending)', NULL, 'Ich hätte gern einen Platz.', '["Ich hätte gern einen Platz.","Ich hätte gern einen Platz"]'::jsonb, 'Platz is masculine and the accusative object: einen Platz, not ein Platz.', 'Platz ist maskulin und Akkusativobjekt: einen Platz, nicht ein Platz.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine accusative takes -en: einen Platz.', 'Maskulin Akkusativ: -en, also einen Platz.', 'Common Expressions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5639e5da-2847-5ad7-95b8-21669aeaf428'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4f768f65-365a-50a0-ae41-1b0b707a62d9'::uuid, 'de743614-79eb-46d1-b774-59362fa59fc7'::uuid, 4, 'fill_blank', 'Wenn ich eine Familie hätte, ___ ich eine größere Wohnung mieten.', 'If I had a family, I would rent a bigger apartment. Main clause, ich-form. Base form: würde.', NULL, 'würde', '["würde"]'::jsonb, 'The main clause needs würde + infinitive; hätte already carries the Konjunktiv II in the wenn-clause.', 'Der Hauptsatz braucht würde + Infinitiv; hätte trägt den Konjunktiv II schon im wenn-Satz.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'ich takes würde, the same form as er/sie/es.', 'ich nimmt würde, die gleiche Form wie er/sie/es.', 'Conjugating würde'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4f768f65-365a-50a0-ae41-1b0b707a62d9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b7d986c5-df92-51ad-82d5-b06e731c1191'::uuid, 'de743614-79eb-46d1-b774-59362fa59fc7'::uuid, 4, 'fill_blank', '___ ihr uns beim Umzug helfen?', 'Would you (plural, informal) help us with the move? Question, ihr-form. Base form: würde.', NULL, 'Würdet', '["Würdet"]'::jsonb, 'ihr takes würdet, in position 1 for a question.', 'ihr nimmt würdet, an Position 1 in der Frage.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr = würdet.', 'ihr = würdet.', 'Conjugating würde'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b7d986c5-df92-51ad-82d5-b06e731c1191'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e0a4e2cd-a8da-5469-8af4-1d285b9abcaf'::uuid, 'de743614-79eb-46d1-b774-59362fa59fc7'::uuid, 4, 'fill_blank', 'Er ___ das Angebot des Vermieters gern annehmen.', 'He would gladly accept the landlord''s offer. er-form; ''des Vermieters'' is genitive. Base form: würde.', NULL, 'würde', '["würde"]'::jsonb, 'er/sie/es share the würde form, same as ich.', 'er/sie/es teilen die Form würde, wie ich.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'er = würde.', 'er = würde.', 'Conjugating würde'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e0a4e2cd-a8da-5469-8af4-1d285b9abcaf'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f621ee16-348e-5767-befa-3756134f4b6f'::uuid, 'de743614-79eb-46d1-b774-59362fa59fc7'::uuid, 4, 'fill_blank', 'Wir ___ uns über eine schnelle Antwort freuen.', 'We would be happy about a quick reply. wir-form. Base form: würde.', NULL, 'würden', '["würden"]'::jsonb, 'wir takes würden, the same form as sie/Sie.', 'wir nimmt würden, wie sie/Sie.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'wir = würden.', 'wir = würden.', 'Conjugating würde'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f621ee16-348e-5767-befa-3756134f4b6f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '985cc27b-cb3b-59f9-b786-c8c939d5e4ed'::uuid, 'de743614-79eb-46d1-b774-59362fa59fc7'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / gern / eine billigere Wohnung / finden / werden]', 'Write the sentence: I would like to find a cheaper apartment. Konjunktiv II with würde: conjugate ''werden'' to match ''ich''. Start with ''Ich''.', NULL, 'Ich würde gern eine billigere Wohnung finden.', '["Ich würde gern eine billigere Wohnung finden.","Ich würde gern eine billigere Wohnung finden","Ich würde eine billigere Wohnung gern finden.","Ich würde eine billigere Wohnung gern finden"]'::jsonb, 'würde (ich) + gern + object + infinitive at the end.', 'würde (ich) + gern + Objekt + Infinitiv am Ende.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'gern can stand before or after the object; the infinitive stays at the end.', 'gern kann vor oder nach dem Objekt stehen; der Infinitiv bleibt am Ende.', 'Conjugating würde'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '985cc27b-cb3b-59f9-b786-c8c939d5e4ed'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2faef7cd-5de3-5b48-842c-ea88605ee754'::uuid, 'de743614-79eb-46d1-b774-59362fa59fc7'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ihr / uns / sicher / bei der Anmeldung / helfen / werden]', 'Write the sentence: You (plural) would surely help us with the registration. Konjunktiv II with würde: conjugate ''werden'' to match ''ihr''. Start with ''Ihr''.', NULL, 'Ihr würdet uns sicher bei der Anmeldung helfen.', '["Ihr würdet uns sicher bei der Anmeldung helfen.","Ihr würdet uns sicher bei der Anmeldung helfen","Ihr würdet uns bei der Anmeldung sicher helfen.","Ihr würdet uns bei der Anmeldung sicher helfen"]'::jsonb, 'ihr takes würdet; sicher sits between the object and the infinitive phrase.', 'ihr nimmt würdet; sicher steht zwischen Objekt und Infinitivphrase.', NULL, 21, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'würdet is the ihr-form; the infinitive helfen stays at the end.', 'würdet ist die ihr-Form; der Infinitiv helfen bleibt am Ende.', 'Conjugating würde'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2faef7cd-5de3-5b48-842c-ea88605ee754'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '08ae1c3c-4508-5d8d-89f8-3982db73e0a4'::uuid, 'de743614-79eb-46d1-b774-59362fa59fc7'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ohne mehr Geld / wir / keine Reise / machen / werden]', 'Write the sentence: Without more money, we would not take a trip. Konjunktiv II with würde: conjugate ''werden'' to match ''wir''. Start with ''Ohne''.', NULL, 'Ohne mehr Geld würden wir keine Reise machen.', '["Ohne mehr Geld würden wir keine Reise machen.","Ohne mehr Geld würden wir keine Reise machen"]'::jsonb, 'The main clause starts with the adverbial ''Ohne mehr Geld'', so würden takes position 2.', 'Der Hauptsatz beginnt mit ''Ohne mehr Geld''; würden steht dann an Position 2.', NULL, 22, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Adverbial-first main clause: the verb würden stays in position 2.', 'Hauptsatz mit Adverbiale zuerst: das Verb würden bleibt an Position 2.', 'Conjugating würde'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '08ae1c3c-4508-5d8d-89f8-3982db73e0a4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '56946321-9c50-5583-bb7a-f527246a7882'::uuid, 'de743614-79eb-46d1-b774-59362fa59fc7'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Wir würden das Auto meines Bruders kaufen würden."', 'Find the error and write the sentence correctly: "Wir würden das Auto meines Bruders kaufen würden." (only one würde per clause)', NULL, 'Wir würden das Auto meines Bruders kaufen.', '["Wir würden das Auto meines Bruders kaufen.","Wir würden das Auto meines Bruders kaufen"]'::jsonb, 'Only one würde per clause; drop the second ''würden'' at the end.', 'Nur ein würde pro Satz; das zweite ''würden'' am Ende fällt weg.', NULL, 23, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'würden + infinitive (kaufen) is complete; the second würden is redundant.', 'würden + Infinitiv (kaufen) ist vollständig; das zweite würden ist überflüssig.', 'Common Mistakes with Konjunktiv II'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '56946321-9c50-5583-bb7a-f527246a7882'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4993cf4b-452c-52f0-897d-3c0883c61bab'::uuid, 'de743614-79eb-46d1-b774-59362fa59fc7'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Würdest du mir zu antworten?"', 'Find the error and write the sentence correctly: "Würdest du mir zu antworten?" (the infinitive stays a plain infinitive)', NULL, 'Würdest du mir antworten?', '["Würdest du mir antworten?","Würdest du mir antworten"]'::jsonb, 'After würde, the verb stays a plain infinitive (antworten), never ''zu antworten''.', 'Nach würde bleibt das Verb im reinen Infinitiv (antworten), nie ''zu antworten''.', NULL, 24, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'würde + infinitive, no zu.', 'würde + Infinitiv, kein zu.', 'Common Mistakes with Konjunktiv II'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4993cf4b-452c-52f0-897d-3c0883c61bab'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0bb310e4-8fd3-5985-922f-d6f6b653d2fa'::uuid, 'de743614-79eb-46d1-b774-59362fa59fc7'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Wenn er mehr Geduld hat, würde er ruhiger antworten."', 'Find the error and write the sentence correctly: "Wenn er mehr Geduld hat, würde er ruhiger antworten." (hypothetical wenn-clause needs Konjunktiv II)', NULL, 'Wenn er mehr Geduld hätte, würde er ruhiger antworten.', '["Wenn er mehr Geduld hätte, würde er ruhiger antworten.","Wenn er mehr Geduld hätte, würde er ruhiger antworten"]'::jsonb, 'Hypothetical wenn-clauses need Konjunktiv II (hätte), not indicative (hat).', 'Hypothetische wenn-Sätze brauchen Konjunktiv II (hätte), nicht Indikativ (hat).', NULL, 25, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'hat becomes hätte; the whole conditional stays in Konjunktiv II.', 'hat wird zu hätte; der ganze Bedingungssatz bleibt im Konjunktiv II.', 'Common Mistakes with Konjunktiv II'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0bb310e4-8fd3-5985-922f-d6f6b653d2fa'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ee022e35-77f0-577d-95bb-fcac8f3c48cb'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 4, 'fill_blank', 'Die Kundin, ___ ich schreibe, wartet auf eine Antwort.', 'The customer (f.) I''m writing to is waiting for a reply. schreiben + dative, feminine noun.', NULL, 'der', '["der"]'::jsonb, 'schreiben takes the dative, and Kundin is feminine, so the pronoun is der.', 'schreiben + Dativ. Kundin ist feminin: der.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'schreiben + dative. Feminine dative = der.', 'schreiben + Dativ. Feminin Dativ = der.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ee022e35-77f0-577d-95bb-fcac8f3c48cb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9aab2edb-4bec-53d4-93cd-e24c13bb5e69'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 4, 'fill_blank', 'Der Kollege, ___ Büro ich benutze, ist im Urlaub.', 'The colleague whose office I''m using is on vacation. Masculine noun, genitive relative pronoun.', NULL, 'dessen', '["dessen"]'::jsonb, 'der Kollege is masculine, so the genitive relative pronoun is dessen.', 'der Kollege ist maskulin: Genitiv-Relativpronomen dessen.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine/neuter genitive relative pronoun = dessen.', 'Maskulin/Neutrum Genitiv = dessen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9aab2edb-4bec-53d4-93cd-e24c13bb5e69'::uuid);

