SELECT '0bcb79f6-bb06-5a2b-b772-83fb999d1d2a'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 4, 'fill_blank', 'Die Chefin, mit ___ ich telefoniere, ist sehr nett.', 'The boss (f.) I''m talking to on the phone is very nice. mit + dative, feminine noun.', NULL, 'der', '["der"]'::jsonb, 'mit takes the dative, and Chefin is feminine, so the pronoun is der.', 'mit + Dativ. Chefin ist feminin: der.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'mit + dative. Feminine dative = der.', 'mit + Dativ. Feminin Dativ = der.', NULL
