INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7a049d79-2164-539b-8748-ad65bea10d32'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 4, 'fill_blank', 'Die Firmen, für ___ wir arbeiten, sind international.', 'The companies we work for are international. für + accusative, plural noun.', NULL, 'die', '["die"]'::jsonb, 'für takes the accusative, and Firmen is plural, so the pronoun is die.', 'für + Akkusativ. Firmen ist Plural: die.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'für + accusative. Plural accusative = die.', 'für + Akkusativ. Plural Akkusativ = die.', 'Preposition + Relative Pronoun: More Examples'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7a049d79-2164-539b-8748-ad65bea10d32'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4b076cdf-c44c-5585-8707-3006bd13a144'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Firma / bei / ich / arbeiten / sein / erfolgreich]', 'Write the sentence: The company I work for is successful. bei + dative relative pronoun (Relativpronomen ergänzen), feminine noun, arbeiten conjugates to arbeite. The relative clause goes directly after the noun. Start with ''Die Firma''.', NULL, 'Die Firma, bei der ich arbeite, ist erfolgreich.', '["Die Firma, bei der ich arbeite, ist erfolgreich.","Die Firma, bei der ich arbeite, ist erfolgreich"]'::jsonb, 'bei takes the dative, and Firma is feminine, so the pronoun is der.', 'bei + Dativ. Firma ist feminin: der.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Preposition + relative pronoun stay together at the start of the clause.', 'Präposition + Relativpronomen bleiben zusammen am Anfang des Satzes.', 'Preposition + Relative Pronoun: More Examples'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4b076cdf-c44c-5585-8707-3006bd13a144'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'dbb7c125-203a-5c86-bcc6-cd0265659859'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Der Kollege, deren Büro neben meinem liegt, ist neu."', 'Find the error and write the sentence correctly: "Der Kollege, deren Büro neben meinem liegt, ist neu." (masculine noun, genitive)', NULL, 'Der Kollege, dessen Büro neben meinem liegt, ist neu.', '["Der Kollege, dessen Büro neben meinem liegt, ist neu.","Der Kollege, dessen Büro neben meinem liegt, ist neu"]'::jsonb, 'der Kollege is masculine → dessen, not deren.', 'der Kollege ist maskulin → dessen, nicht deren.', NULL, 14, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine/neuter genitive relative pronoun = dessen, not deren.', 'Maskulin/Neutrum Genitiv = dessen, nicht deren.', 'Common Mistakes: Preposition, dessen/deren, Comma'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'dbb7c125-203a-5c86-bcc6-cd0265659859'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c373924c-6148-54f8-9ab1-01c62841df8c'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Nachbarin / Garten / sein / schön / helfen / oft]', 'Write the sentence: The neighbour (f.) whose garden is beautiful often helps. Possessive relative pronoun for a feminine noun (Relativpronomen ergänzen), sein conjugates to ist, helfen conjugates to hilft. The relative clause goes directly after the noun. Start with ''Die Nachbarin''.', NULL, 'Die Nachbarin, deren Garten schön ist, hilft oft.', '["Die Nachbarin, deren Garten schön ist, hilft oft.","Die Nachbarin, deren Garten schön ist, hilft oft"]'::jsonb, 'die Nachbarin is feminine, so the genitive relative pronoun is deren.', 'die Nachbarin ist feminin: Genitiv-Relativpronomen deren.', NULL, 15, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine/plural genitive relative pronoun = deren.', 'Feminin/Plural Genitiv = deren.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c373924c-6148-54f8-9ab1-01c62841df8c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '145e61f5-7694-52cf-917c-dcea038d8b93'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Der Vertrag, über die wir sprechen, ist kompliziert."', 'Find the error and write the sentence correctly: "Der Vertrag, über die wir sprechen, ist kompliziert." (masculine noun, accusative preposition)', NULL, 'Der Vertrag, über den wir sprechen, ist kompliziert.', '["Der Vertrag, über den wir sprechen, ist kompliziert.","Der Vertrag, über den wir sprechen, ist kompliziert"]'::jsonb, 'der Vertrag is masculine. über + accusative = den.', 'der Vertrag ist maskulin. über + Akkusativ: den.', NULL, 16, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'über + accusative. Masculine accusative = den, not die.', 'über + Akkusativ. Maskulin Akkusativ = den, nicht die.', 'Preposition + Relative Pronoun: More Examples'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '145e61f5-7694-52cf-917c-dcea038d8b93'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'abc5847b-19bf-5623-beca-9608f2919125'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Kunden / von / ich / sprechen / sein / zufrieden]', 'Write the sentence: The customers I''m talking about are satisfied. von + dative plural relative pronoun (Relativpronomen ergänzen), sprechen conjugates to spreche, sein conjugates to sind. The relative clause goes directly after the noun. Start with ''Die Kunden''.', NULL, 'Die Kunden, von denen ich spreche, sind zufrieden.', '["Die Kunden, von denen ich spreche, sind zufrieden.","Die Kunden, von denen ich spreche, sind zufrieden"]'::jsonb, 'von takes the dative, and Kunden is plural, so the pronoun is denen.', 'von + Dativ. Kunden ist Plural: denen.', NULL, 17, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Plural dative relative pronoun after a preposition = denen.', 'Plural Dativ-Relativpronomen nach Präposition = denen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'abc5847b-19bf-5623-beca-9608f2919125'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c52b3ac1-4197-5218-ac5f-3cc9686757b6'::uuid, 'ad9deedc-7765-4c06-b4d0-0c511644f311'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Die Frau, die Sohn hier arbeitet, ist neu."', 'Find the error and write the sentence correctly: "Die Frau, die Sohn hier arbeitet, ist neu." (missing genitive relative pronoun)', NULL, 'Die Frau, deren Sohn hier arbeitet, ist neu.', '["Die Frau, deren Sohn hier arbeitet, ist neu.","Die Frau, deren Sohn hier arbeitet, ist neu"]'::jsonb, 'die Frau is feminine, so the genitive relative pronoun is deren, not die.', 'die Frau ist feminin: Genitiv-Relativpronomen deren, nicht die.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine genitive relative pronoun = deren.', 'Feminin Genitiv = deren.', 'Common Mistakes: Preposition, dessen/deren, Comma'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c52b3ac1-4197-5218-ac5f-3cc9686757b6'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c3e537eb-5c1f-5c06-bfb8-dd567d8c7f82'::uuid, 'd1728914-c761-408f-9b9a-81c6c4a4e305'::uuid, 4, 'fill_blank', 'Der Lehrer, ___ uns Deutsch beibringt, ist streng.', 'The teacher who teaches us German is strict. No other subject in the relative clause, masculine noun → nominative case.', NULL, 'der', '["der"]'::jsonb, 'The relative pronoun is the subject of ''beibringt'' → nominative. Masculine → der.', 'Relativpronomen ist SUBJEKT von ''beibringt'' → Nominativ. Maskulin → der.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'No other subject present = nominative. Masculine = der.', 'Kein anderes Subjekt = Nominativ. Maskulin = der.', 'Nominative Relative Pronouns (Subject)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c3e537eb-5c1f-5c06-bfb8-dd567d8c7f82'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '825a4ecb-3f6f-504f-be92-56bcc5a889cb'::uuid, 'd1728914-c761-408f-9b9a-81c6c4a4e305'::uuid, 4, 'fill_blank', 'Die Ärztin, ___ mich behandelt, ist sehr freundlich.', 'The doctor (f.) who treats me is very friendly. No other subject, feminine noun → nominative case.', NULL, 'die', '["die"]'::jsonb, 'The relative pronoun is the subject of ''behandelt'' → nominative. Feminine → die.', 'Relativpronomen ist SUBJEKT von ''behandelt'' → Nominativ. Feminin → die.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Subject of ''behandelt'' = nominative. Feminine = die.', 'Subjekt von ''behandelt'' = Nominativ. Feminin = die.', 'Nominative Relative Pronouns (Subject)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '825a4ecb-3f6f-504f-be92-56bcc5a889cb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '59f6d6c4-f4fe-5621-ae5d-d9256efe39dd'::uuid, 'd1728914-c761-408f-9b9a-81c6c4a4e305'::uuid, 4, 'fill_blank', 'Das Auto, ___ ich verkaufe, ist zehn Jahre alt.', 'The car that I am selling is ten years old. ''ich'' is the subject, so the pronoun is the object → accusative case, neuter noun.', NULL, 'das', '["das"]'::jsonb, '''ich'' is the subject, so the relative pronoun is the object → accusative. Neuter → das.', '''ich'' ist Subjekt → Relativpronomen ist Objekt → Akkusativ. Neutrum → das.', NULL, 18, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Another subject (ich) present = accusative. Neuter accusative = das.', 'Anderes Subjekt (ich) vorhanden = Akkusativ. Neutrum Akkusativ = das.', 'Accusative Relative Pronouns (Object)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '59f6d6c4-f4fe-5621-ae5d-d9256efe39dd'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bf2c75b5-1b62-5469-a157-930877bb53ec'::uuid, 'd1728914-c761-408f-9b9a-81c6c4a4e305'::uuid, 4, 'fill_blank', 'Die Nachrichten, ___ ich heute lese, sind wichtig.', 'The news that I am reading today is important. ''ich'' is the subject, so the pronoun is the object → accusative case, plural noun.', NULL, 'die', '["die"]'::jsonb, '''ich'' is the subject, so the relative pronoun is the object → accusative. Plural → die.', '''ich'' ist Subjekt → Relativpronomen ist Objekt → Akkusativ. Plural → die.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Another subject present = accusative. Plural accusative = die.', 'Anderes Subjekt vorhanden = Akkusativ. Plural Akkusativ = die.', 'Accusative Relative Pronouns (Object)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bf2c75b5-1b62-5469-a157-930877bb53ec'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4e16bf7f-3337-5e21-a539-85436b5a009f'::uuid, 'd1728914-c761-408f-9b9a-81c6c4a4e305'::uuid, 5, 'sentence_building', 'Schreib den Satz: [der Nachbar / jeden Abend / Gitarre / spielen / sein / nervig]', 'Write the sentence: The neighbour who plays guitar every evening is annoying. Relative pronoun is subject of ''spielt'' → nominative, masculine (Relativpronomen ergänzen). spielen conjugates to spielt, sein conjugates to ist. The relative clause goes directly after the noun. Start with ''Der Nachbar''.', NULL, 'Der Nachbar, der jeden Abend Gitarre spielt, ist nervig.', '["Der Nachbar, der jeden Abend Gitarre spielt, ist nervig.","Der Nachbar, der jeden Abend Gitarre spielt, ist nervig"]'::jsonb, 'The relative pronoun is the subject of ''spielt'' → nominative. Masculine → der.', 'Relativpronomen ist Subjekt von ''spielt'' → Nominativ. Maskulin → der.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'No other subject in the relative clause = nominative.', 'Kein anderes Subjekt im Relativsatz = Nominativ.', 'Nominative Relative Pronouns (Subject)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4e16bf7f-3337-5e21-a539-85436b5a009f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c74ce1ad-11e9-556a-ab16-10b680e72f6b'::uuid, 'd1728914-c761-408f-9b9a-81c6c4a4e305'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Der Termin, die ich habe, ist wichtig."', 'Find the error and write the sentence correctly: "Der Termin, die ich habe, ist wichtig." (masculine noun, object)', NULL, 'Der Termin, den ich habe, ist wichtig.', '["Der Termin, den ich habe, ist wichtig.","Der Termin, den ich habe, ist wichtig"]'::jsonb, '''ich'' is the subject, so the relative pronoun is the object → accusative. Termin is masculine → den.', '''ich'' ist Subjekt → Objekt → Akkusativ. Termin ist maskulin → den.', NULL, 21, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine accusative = den, not die.', 'Maskulin Akkusativ = den, nicht die.', 'Common Mistakes with Relative Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c74ce1ad-11e9-556a-ab16-10b680e72f6b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5ab6fc0d-7c7a-589d-8b04-6377e623cf02'::uuid, 'd1728914-c761-408f-9b9a-81c6c4a4e305'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Kollegin / ich / schon lange / kennen / wohnen / in Berlin]', 'Write the sentence: The colleague (f.) whom I''ve known for a long time lives in Berlin. ''ich'' is the subject, so the pronoun is the object, accusative feminine (Relativpronomen ergänzen). kennen conjugates to kenne, wohnen conjugates to wohnt. The relative clause goes directly after the noun. Start with ''Die Kollegin''.', NULL, 'Die Kollegin, die ich schon lange kenne, wohnt in Berlin.', '["Die Kollegin, die ich schon lange kenne, wohnt in Berlin.","Die Kollegin, die ich schon lange kenne, wohnt in Berlin"]'::jsonb, '''ich'' is the subject, so the relative pronoun is the object → accusative. Feminine accusative = die (same as nominative).', '''ich'' ist Subjekt → Objekt → Akkusativ. Feminin Akkusativ = die (gleich wie Nominativ).', NULL, 22, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine accusative = die, same form as nominative.', 'Feminin Akkusativ = die, gleiche Form wie Nominativ.', 'Accusative Relative Pronouns (Object)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5ab6fc0d-7c7a-589d-8b04-6377e623cf02'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '774f5c20-5a76-5851-9341-8a14329ef868'::uuid, 'd1728914-c761-408f-9b9a-81c6c4a4e305'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Das Formular, dass ich brauche, liegt auf dem Tisch."', 'Find the error and write the sentence correctly: "Das Formular, dass ich brauche, liegt auf dem Tisch." (relative pronoun, not conjunction)', NULL, 'Das Formular, das ich brauche, liegt auf dem Tisch.', '["Das Formular, das ich brauche, liegt auf dem Tisch.","Das Formular, das ich brauche, liegt auf dem Tisch"]'::jsonb, 'DAS (one s) is the relative pronoun. dass (double s) is the conjunction ''that''.', 'DAS (ein s) ist das Relativpronomen. dass (zwei s) ist die Konjunktion.', NULL, 23, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Relative pronoun = das, not dass.', 'Relativpronomen = das, nicht dass.', 'Common Mistakes with Relative Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '774f5c20-5a76-5851-9341-8a14329ef868'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2c0e5e8f-0cf7-5af3-8259-b3dc693d12b6'::uuid, 'd1728914-c761-408f-9b9a-81c6c4a4e305'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Prüfung / wir / bestehen / wollen / sein / schwer]', 'Write the sentence: The exam that we want to pass is difficult. ''wir'' is the subject, so the pronoun is the object, accusative feminine (Relativpronomen ergänzen). bestehen wollen keeps the modal at the end, sein conjugates to ist. The relative clause goes directly after the noun. Start with ''Die Prüfung''.', NULL, 'Die Prüfung, die wir bestehen wollen, ist schwer.', '["Die Prüfung, die wir bestehen wollen, ist schwer.","Die Prüfung, die wir bestehen wollen, ist schwer"]'::jsonb, '''wir'' is the subject, so the relative pronoun is the object → accusative. Feminine accusative = die.', '''wir'' ist Subjekt → Objekt → Akkusativ. Feminin Akkusativ = die.', NULL, 24, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Modal verb (wollen) goes to the very end of the relative clause.', 'Modalverb (wollen) steht ganz am Ende des Relativsatzes.', 'Nominative vs Accusative: How to Choose'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2c0e5e8f-0cf7-5af3-8259-b3dc693d12b6'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6f3f6d72-b807-5030-ada7-40adbec3bd56'::uuid, 'd1728914-c761-408f-9b9a-81c6c4a4e305'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Der Kunde, den schon lange wartet, ist ungeduldig."', 'Find the error and write the sentence correctly: "Der Kunde, den schon lange wartet, ist ungeduldig." (subject of an intransitive verb)', NULL, 'Der Kunde, der schon lange wartet, ist ungeduldig.', '["Der Kunde, der schon lange wartet, ist ungeduldig.","Der Kunde, der schon lange wartet, ist ungeduldig"]'::jsonb, '''wartet'' has no object. Der Kunde is the subject itself → nominative der.', '''wartet'' hat kein Objekt. Der Kunde ist selbst das Subjekt → Nominativ der.', NULL, 25, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'warten has no object, so the relative pronoun is the subject: nominative der.', 'warten hat kein Objekt, also ist das Relativpronomen Subjekt: Nominativ der.', 'Common Mistakes with Relative Clauses'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6f3f6d72-b807-5030-ada7-40adbec3bd56'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a9823bda-b963-500f-81f0-d9d1d469d372'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 4, 'fill_blank', 'Sie lernt jeden Abend Vokabeln, ___ die Prüfung im Juni zu schaffen.', 'She studies vocabulary every evening in order to pass the exam in June. Purpose. Base form: um.', NULL, 'um', '["um"]'::jsonb, 'um ... zu expresses purpose: why she studies vocabulary every evening.', 'um ... zu drückt Zweck aus: warum sie jeden Abend Vokabeln lernt.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'um ... zu = in order to.', 'um ... zu = Zweck.', 'um ... zu (in order to)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a9823bda-b963-500f-81f0-d9d1d469d372'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6fe4f7ad-f546-526a-815d-7661dde36343'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 4, 'fill_blank', 'Sie hat die Wohnung verlassen, ___ das Licht auszuschalten, und musste noch einmal zurückgehen.', 'She left the apartment without turning off the light, and had to go back again. Absence of action. Base form: ohne.', NULL, 'ohne', '["ohne"]'::jsonb, 'ohne ... zu says what she left undone; going back again only makes sense if she forgot.', 'ohne ... zu sagt, was jemand nicht macht.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ohne ... zu = without + -ing.', 'ohne ... zu sagt, was fehlt.', 'ohne ... zu (without doing)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6fe4f7ad-f546-526a-815d-7661dde36343'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5d49e458-1b72-5a99-bf2a-e65c0c64d0f2'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 4, 'fill_blank', '___ Kaffee zu trinken, nimmt er Tee.', 'Instead of drinking coffee, he has tea. Alternative action, sentence start. Base form: anstatt.', NULL, 'Anstatt', '["Anstatt","Statt"]'::jsonb, 'anstatt/statt ... zu = instead of doing.', 'anstatt/statt ... zu nennt die Alternative.', NULL, 11, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'anstatt/statt ... zu = instead of + -ing.', 'anstatt/statt ... zu nennt, was stattdessen passiert.', 'anstatt/statt ... zu (instead of doing)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5d49e458-1b72-5a99-bf2a-e65c0c64d0f2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '85e38ba7-3a9f-5a7c-9f0a-dfcaa6476d52'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 4, 'fill_blank', 'Ich rufe früh an, um einen Termin zu ___.', 'I call early in order to get an appointment. Infinitive after zu. Base form: bekommen.', NULL, 'bekommen', '["bekommen"]'::jsonb, 'zu + infinitive at the end of the um-clause.', 'zu + Infinitiv am Ende des um-Satzes.', NULL, 12, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'After zu comes the plain infinitive.', 'Nach zu kommt der reine Infinitiv.', 'um ... zu (in order to)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '85e38ba7-3a9f-5a7c-9f0a-dfcaa6476d52'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b5058aa5-59c0-59c9-bc02-200ea4005b72'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / aufstehen / früh / um / fit / zu / sein]', 'Write the sentence: I get up early in order to be fit. Conjugate ''aufstehen'' for ''ich'' (separable: ich stehe ... auf); the um-clause ends in ''zu sein''. Start with ''Ich''.', NULL, 'Ich stehe früh auf, um fit zu sein.', '["Ich stehe früh auf, um fit zu sein.","Ich stehe früh auf, um fit zu sein"]'::jsonb, 'Main clause: ich stehe früh auf (separable). um-clause: um fit zu sein, zu + infinitive at the end.', 'Hauptsatz: ich stehe früh auf (trennbar). um-Satz: um fit zu sein, zu + Infinitiv am Ende.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Separable auf in the main clause; um ... zu sein as the purpose clause.', 'Trennbares auf im Hauptsatz; um ... zu sein als Zwecksatz.', 'um ... zu (in order to)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b5058aa5-59c0-59c9-bc02-200ea4005b72'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6f1e2563-6703-5aa3-a6c3-3679fc8083d3'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 5, 'sentence_building', 'Schreib den Satz: [er / die Party / verlassen / ohne / sich / zu / bedanken]', 'Write the sentence: He left the party without saying thank you. Use the Perfekt of verlassen: er hat die Party verlassen. ohne ... zu + reflexive verb at the end. Start with ''Er''.', NULL, 'Er hat die Party verlassen, ohne sich zu bedanken.', '["Er hat die Party verlassen, ohne sich zu bedanken.","Er hat die Party verlassen, ohne sich zu bedanken"]'::jsonb, 'Perfekt (hat verlassen) + ohne ... zu bedanken as the absence-of-action clause.', 'Perfekt (hat verlassen) + ohne ... zu bedanken als Satz für die fehlende Handlung.', NULL, 14, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'hat verlassen (Perfekt) + ohne + reflexive zu-infinitive at the end.', 'hat verlassen (Perfekt) + ohne + reflexiver zu-Infinitiv am Ende.', 'ohne ... zu (without doing)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6f1e2563-6703-5aa3-a6c3-3679fc8083d3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd3e6bf71-59c1-51b9-920d-e78d92f7f827'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / Geld / sparen / anstatt / einkaufen / zu / gehen]', 'Write the sentence: We save money instead of going shopping. Conjugate ''sparen'' for ''wir''. Start with ''Wir''.', NULL, 'Wir sparen Geld, anstatt einkaufen zu gehen.', '["Wir sparen Geld, anstatt einkaufen zu gehen.","Wir sparen Geld, anstatt einkaufen zu gehen"]'::jsonb, 'Main clause first, then anstatt ... zu gehen as the alternative-action clause.', 'Zuerst der Hauptsatz, dann anstatt ... zu gehen als Satz für die Alternative.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'anstatt + einkaufen + zu + gehen: zu sits right before the infinitive gehen.', 'anstatt + einkaufen + zu + gehen: zu steht direkt vor dem Infinitiv gehen.', 'anstatt/statt ... zu (instead of doing)'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd3e6bf71-59c1-51b9-920d-e78d92f7f827'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c66049a1-3f75-53ca-8b28-a5ad3d77a70a'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Er ging, ohne grüßen."', 'Find the error and write the sentence correctly: "Er ging, ohne grüßen." (ohne needs zu before the infinitive)', NULL, 'Er ging, ohne zu grüßen.', '["Er ging, ohne zu grüßen.","Er ging, ohne zu grüßen"]'::jsonb, 'ohne + infinitive always needs zu: ohne zu grüßen.', 'ohne + Infinitiv braucht immer zu: ohne zu grüßen.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'ohne ... zu + infinitive is the fixed pattern.', 'ohne ... zu + Infinitiv ist das feste Muster.', 'Common Mistakes with um/ohne/(an)statt ... zu'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c66049a1-3f75-53ca-8b28-a5ad3d77a70a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'dc57d493-c452-50e3-bdbb-4d02fb07089b'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Anstatt zum Arzt gehen, ruft sie bei der Praxis an."', 'Find the error and write the sentence correctly: "Anstatt zum Arzt gehen, ruft sie bei der Praxis an." (anstatt needs zu before the infinitive)', NULL, 'Anstatt zum Arzt zu gehen, ruft sie bei der Praxis an.', '["Anstatt zum Arzt zu gehen, ruft sie bei der Praxis an.","Anstatt zum Arzt zu gehen, ruft sie bei der Praxis an"]'::jsonb, 'anstatt + infinitive needs zu: anstatt zum Arzt zu gehen.', 'anstatt + Infinitiv braucht zu: anstatt zum Arzt zu gehen.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'anstatt ... zu + infinitive is the fixed pattern.', 'anstatt ... zu + Infinitiv ist das feste Muster.', 'Common Mistakes with um/ohne/(an)statt ... zu'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'dc57d493-c452-50e3-bdbb-4d02fb07089b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e0d3593d-18a4-5ad5-8c00-9fd22b02f3d6'::uuid, '1f391943-8ab9-4a5e-af92-9fba1a8a6010'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Sie ruft bei der Krankenkasse an ohne ihre Nummer zu nennen."', 'Find the error and write the sentence correctly: "Sie ruft bei der Krankenkasse an ohne ihre Nummer zu nennen." (missing comma)', NULL, 'Sie ruft bei der Krankenkasse an, ohne ihre Nummer zu nennen.', '["Sie ruft bei der Krankenkasse an, ohne ihre Nummer zu nennen.","Sie ruft bei der Krankenkasse an, ohne ihre Nummer zu nennen"]'::jsonb, 'A comma comes before ohne ... zu when it introduces an extended infinitive clause.', 'Vor ohne ... zu (erweiterter Infinitivsatz) steht ein Komma.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Comma marks the start of the ohne-clause.', 'Das Komma markiert den Beginn des ohne-Satzes.', 'Common Mistakes with um/ohne/(an)statt ... zu'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e0d3593d-18a4-5ad5-8c00-9fd22b02f3d6'::uuid);


